/* ---------------------------------------------------------------------------
   CB_S187A - CAA 2001 s.187A: which requirement applies, on which clock.
   Board items A-6 (12921347006), A-5 (12921347005), A-1 (12921346992),
   A-4 (12921347004). Rulebook: Statutory Rules Register A, Addendum 1
   (the two-year fixed-value window), rows A-F1 to A-F30.

   WHAT WAS WRONG, AND WHY IT WAS FOUR DEFECTS AND NOT ONE

   The engine had a single fixed-value question that asked the client whether
   two years had passed since THEY took on the property, and treated the answer
   as decisive. Three separate things are wrong with that, and a fourth was
   missing entirely:

     A-6  Nothing recorded which item of the s.196 Table the PAST OWNER's
          disposal fell under. That item is the fork in the statute: items
          1, 5 and 9 lead to the fixed value requirement, items 2 and 3 and
          s.61 item 7 lead to the disposal value statement requirement, and
          the two are different tests on different clocks. Without it the
          engine could not choose, so it always behaved as though the first
          fork had been taken. A-6 is built FIRST because A-1 and A-4 both
          read what it captures.

     A-5  No past_owner_cessation_date. Both FA 2012 Sch 10 para 13
          transitionals gate on when the PAST OWNER ceased to be treated as
          owning the plant - para 13(1) for whether the regime applies at
          all, para 13(2) for whether the pooling requirement does. The
          engine had only the client's own acquisition date, which is a
          different date whenever anyone sits between the two.

     A-1  s.187A(9) does not run the clock from the client's acquisition. It
          runs it from the acquisition by THE PURCHASER FROM THE PAST OWNER
          (items 1 and 9), or from the grant of the lease to the lessee
          (item 5). Where a developer, charity, housing association or
          non-claiming propco sits in between, the window opened and closed
          around a transaction our client was not party to - and may have
          expired before they were involved at all. The engine reported a
          live window on a claim that died years earlier. HMRC's own pages
          disagree with each other here: CA26480 states the statutory rule,
          CA26478 glosses it as running from the new owner's acquisition,
          and the shipped question paraphrased the gloss.

     A-4  There was no disposal value statement branch anywhere. s.187A(3)(c),
          (10) and (11) were unreachable, so the item 2 / item 3 / s.61 item 7
          cases returned a figure where the law returns nil.

   THE RULE THIS MODULE IS BUILT ON: UNKNOWN IS NOT A BRANCH

   Every gate below that would RELIEVE the client - switch the regime off,
   switch the pooling requirement off, treat a window as open, treat a
   statement as in time - fires only on a date that is actually known. An
   absent or unparseable date leaves the restriction in force and raises a
   capture flag. This is deliberate and it is the reason defect F-2 exists on
   this board: an unknown grant that defaulted to nil silently inflated
   claims. The same trap is available here in at least four places and is
   closed in all four.

   WHAT THIS MODULE DELIBERATELY DOES NOT DO

     A-2 (12921346993, gated on A-Q8) is the s.187A(6)(b) statements route -
     a third way of satisfying the fixed value requirement, with no time
     limit. It is NOT built here. That is why a closed window returns INDET
     with a named capture step and never a settled NIL: returning NIL would
     silently decide A-2 against the client.

     A-3 (12921346994, gated on B-Q4) is the test of whether the fixed value
     requirement applies at all where the past owner never claimed. The
     existing gating is left exactly as it was.

   Neither is coded, and no rule below depends on either being resolved.
   --------------------------------------------------------------------------- */
var CB_S187A = (function(){

  /* Which item of the s.196 Table (or s.61) the past owner's disposal fell
     under. Values are the rulebook's, not invented here. */
  var ITEM = {
    I1:      "196/1",    /* cessation of ownership on a sale of the interest    */
    I2:      "196/2",    /* the same, at less than market value                 */
    I3:      "196/3",    /* cessation where neither 1 nor 2 applies             */
    I5:      "196/5",    /* lessee became owner under s.183                     */
    I9:      "196/9",    /* permanent discontinuance, then sale of interest     */
    S61_7:   "61/7",     /* permanent discontinuance of the qualifying activity */
    UNKNOWN: "unknown"
  };

  /* Which requirement that item leads to. */
  var TRACK = {
    FVR:     "FVR",      /* fixed value requirement - s.187A(5)-(9)      */
    DVS:     "DVS",      /* disposal value statement - s.187A(10)-(11)   */
    UNKNOWN: "UNKNOWN"
  };

  var OUT = {
    OFF:    "OFF",       /* s.187A does not apply at all (A-F1)            */
    LIVE:   "LIVE",      /* window open, both routes still available       */
    CAP_DV: "CAP-DV",    /* satisfied; capped at the stated disposal value */
    NIL:    "NIL",       /* requirement applies and is not satisfied       */
    SATIS:  "SATISFIED",  /* a relevant apportionment was made (A-F12)     */
    INDET:  "INDET"      /* cannot be established; conservative floor nil  */
  };

  var TWO_YEARS_MS = 2 * 365.25 * 24 * 60 * 60 * 1000;

  function parseDate(v){
    if(!v) return null;
    var d = (v instanceof Date) ? v : new Date(v);
    return isNaN(d.getTime()) ? null : d;
  }

  function now(s){
    if(s && s.__now) return parseDate(s.__now) || new Date();
    return new Date();
  }

  /* -------------------------------------------------------------------------
     A-6 - which s.196 Table item, DERIVED and never asked.

     The client cannot be asked "which item of the s.196 Table did the past
     owner's disposal fall under". They can be asked what happened, which is
     what the question set below does; the classification is done here. This
     follows the precedent already set on this board by the amendment window,
     which is derived from the acquisition date and the accounting period
     rather than put to the client (item 12829962267), and by
     CB_ELECTION.section, which derives the item for the CLIENT's own
     transaction from exactly this kind of lay fact.

     NOTE ON A SOURCE CONFLICT - FIRST RESOLVED THE WRONG WAY, AND REVERSED ON
     13 SEPTEMBER 2026 BY PHASE 129a. Rulebook A Addendum 1 row T23 glosses
     item 9 as "permanent discontinuance followed by sale of the qualifying
     interest", and that is what the s.196 Table says (legislation.gov.uk,
     read 12 and 13 September 2026). Rulebook C row E1/E-A2 and
     CB_ELECTION.section had item 9 as an incoming lessee's premium with no
     s.183 election, taken from CA26800, which names no Table item. This note
     used to follow those two because they agreed with each other. Two of our
     own artefacts agreeing is not a source; the Table governs, T23 is right,
     and Rulebook C now carries the corrected rows.
     THE CODE DOES NOT MOVE ON ITS OWN. A lease premium with no s.183 election
     still returns I9 on the fixed value track while
     CB_CTA.lease_premium_not_item9 is off, because that is today's behaviour
     and which route those facts do take is the tax adviser's question. With
     the switch on it returns the UNKNOWN track with a capture step naming the
     adviser. The real item 9 - a discontinuance followed by a sale - has no
     case of its own: it is answered today as "sold_market", item 1, which is
     the same fixed value track on the same clock, so no outcome turns on it.
     ------------------------------------------------------------------------- */
  function disposalItem(s){
    s = s || {};

    switch(s.past_owner_disposal_mode){

      case "sold_market":
        return { item:ITEM.I1, track:TRACK.FVR,
                 why:"the earlier owner sold the property on ordinary open-market terms — s.196 Table item 1" };

      case "new_lease_premium":
        if(s.past_owner_s183_election === "yes")
          return { item:ITEM.I5, track:TRACK.FVR,
                   why:"the earlier owner granted a new lease for a premium and made a joint election with the incoming tenant — s.196 Table item 5" };
        if(s.past_owner_s183_election === "no" && CB_CTA.lease_premium_not_item9)
          return { item:ITEM.UNKNOWN, track:TRACK.UNKNOWN, switched:"lease_premium_not_item9",
                   why:"the earlier owner granted a new lease for a premium with no joint election. Which item of the s.196 Table that falls under is not established — item 9 is a permanent discontinuance followed by a sale, not a lease — so it is not yet known which of the two statutory requirements applies. This is a switched position (CB_CTA.lease_premium_not_item9) that stands only if a chartered tax adviser has answered it that way",
                   action:"route not established — put to the tax adviser: which item of the s.196 Table, if any, applies where a lease is granted for a premium with no joint election. Asking the client again will not settle it" };
        if(s.past_owner_s183_election === "no")
          return { item:ITEM.I9, track:TRACK.FVR,
                   why:"the earlier owner granted a new lease for a premium with no joint election — s.196 Table item 9" };
        return { item:ITEM.UNKNOWN, track:TRACK.UNKNOWN,
                 why:"the earlier owner granted a new lease for a premium, but whether a joint election was made with the incoming tenant is not known — that single fact decides which item of the s.196 Table applies" };

      case "sold_undervalue":
        return { item:ITEM.I2, track:TRACK.DVS,
                 why:"the earlier owner transferred the property for less than it was worth — s.196 Table item 2, which leads to the disposal value statement requirement and not to the fixed value requirement" };

      case "ceased_no_sale":
        return { item:ITEM.I3, track:TRACK.DVS,
                 why:"the earlier owner stopped owning the fixtures without a sale of the interest — s.196 Table item 3, which leads to the disposal value statement requirement" };

      case "discontinued_trade":
        return { item:ITEM.S61_7, track:TRACK.DVS,
                 why:"the earlier owner permanently stopped trading from the property and brought a disposal value into account without selling — s.61 Table item 7, which leads to the disposal value statement requirement" };

      default:
        return { item:ITEM.UNKNOWN, track:TRACK.UNKNOWN,
                 why:"how the earlier owner stopped owning the fixtures has not been established, so it is not yet known which of the two statutory requirements applies" };
    }
  }

  /* -------------------------------------------------------------------------
     A-5 - FA 2012 Sch 10 paras 11 and 13, both keyed on the PAST OWNER's
     cessation of ownership.

     para 11     the s.187A regime has effect for new expenditure incurred on
                 or after 1 April 2012 (CT) / 6 April 2012 (IT). The split
                 follows the CURRENT owner's charge, because it is the current
                 owner's new expenditure the paragraph speaks of.
     para 13(1)  a period of ownership that BEGAN AND ENDED before that date is
                 not a relevant earlier time. A period cannot end before it
                 begins, so a cessation earlier than the commencement date is
                 by itself sufficient - no separate start date is needed.
     para 13(2)  the pooling requirement does not apply where the past owner's
                 period of ownership ends no later than TWO YEARS after that
                 date.

     Both paragraphs RELIEVE, so both fire only on a known date.
     ------------------------------------------------------------------------- */
  function commencementDate(s){
    return ((s && s.claimant_type) === "company")
      ? new Date("2012-04-01T00:00:00Z")
      : new Date("2012-04-06T00:00:00Z");
  }

  /* para 13(1) - is the regime switched off for this past owner? */
  function regimeOff(s){
    s = s || {};
    var cess = parseDate(s.past_owner_cessation_date);
    if(!cess) return false;                       /* unknown -> regime stays on */
    return cess < commencementDate(s);
  }

  /* para 13(2) - is the pooling requirement in force? */
  function poolingRequirementInForce(s){
    s = s || {};
    var cess = parseDate(s.past_owner_cessation_date);
    if(!cess) return true;                        /* unknown -> stays in force */
    var limit = new Date(commencementDate(s).getTime() + TWO_YEARS_MS);
    return cess > limit;
  }

  /* -------------------------------------------------------------------------
     A-1 - who the purchaser from the past owner is, and therefore which
     acquisition date starts the relevant 2 year period.

     The engine already knows enough to derive this in the two clear cases:
     a seller who was themselves entitled IS the past owner, so the client
     bought directly from them; a seller who was NOT entitled, sitting in
     front of an earlier owner who WAS, is by definition an intervening owner.
     Everything else is unsure, and unsure does not resolve in the client's
     favour. An explicit answer, where one has been given, wins over the
     derivation.
     ------------------------------------------------------------------------- */
  function interveningOwner(s){
    s = s || {};
    if(s.intervening_owner === "yes" || s.intervening_owner === "no") return s.intervening_owner;
    if(s.prior_owner_entitled === "yes") return "no";
    if(s.prior_owner_entitled === "no" && s.earlier_entitled_owner === "yes") return "yes";
    return "unsure";
  }

  /* The start of the relevant 2 year period - s.187A(9). */
  function windowStart(s){
    s = s || {};
    var di = disposalItem(s);
    var iv = interveningOwner(s);

    /* Item 5: the clock runs from the grant of the lease to that lessee,
       whoever the client is. s.187A(9)(b). */
    if(di.item === ITEM.I5){
      var g = parseDate(s.past_owner_lease_grant_date) || (iv === "no" ? parseDate(s.grant_date) : null);
      if(g) return { date:g, derivable:true, basis:"lease_grant",
                     why:"the two-year period runs from the grant of that lease (s.187A(9)(b))" };
      return { date:null, derivable:false, basis:"lease_grant",
               why:"the two-year period runs from the grant of the lease to the incoming tenant, and that date is not known" };
    }

    if(di.item === ITEM.UNKNOWN)
      return { date:null, derivable:false, basis:null,
               why:"which item of the s.196 Table applies is not established, so the start of the two-year period cannot be fixed" };

    /* CL-1 (Phase 129, 12 September 2026) - CB_CTA.fvr_clock_from_client_purchase.
       Off, as shipped at Phase 50: the branches below, s.187A(9)(a). On: the
       CA26478 gloss - the period runs from the client's own acquisition
       whoever sat in between. The client's date must still be KNOWN; an
       unknown date is not derivable on this reading either (N4). */
    if(CB_CTA.fvr_clock_from_client_purchase){
      var own = parseDate(s.acquisition_date);
      if(own) return { date:own, derivable:true, basis:"client_acquisition",
                       why:"the two-year period has been run from your own completion date, whoever owned the property in between — a switched position (CB_CTA.fvr_clock_from_client_purchase) that stands only if a chartered tax adviser has answered it that way" };
      return { date:null, derivable:false, basis:"client_acquisition",
               why:"your completion date has not been given, so the two-year period cannot be fixed" };
    }

    /* Items 1 and 9: from the acquisition by the purchaser from the past
       owner - s.187A(9)(a). */
    if(iv === "no"){
      var a = parseDate(s.acquisition_date);
      if(a) return { date:a, derivable:true, basis:"client_acquisition",
                     why:"you bought directly from the owner who last claimed, so the two-year period runs from your own completion date (s.187A(9)(a))" };
      return { date:null, derivable:false, basis:"client_acquisition",
               why:"your completion date has not been given, so the two-year period cannot be fixed" };
    }

    var ivd = parseDate(s.intervening_owner_acquisition_date);
    if(ivd) return { date:ivd, derivable:true, basis:"intervening_acquisition",
                     why:"someone else owned the property between the last owner who claimed and you, so the two-year period runs from THEIR purchase date and not yours (s.187A(9)(a))" };

    return { date:null, derivable:false, basis:"intervening_acquisition",
             why:(iv === "yes")
               ? "someone else owned the property between the last owner who claimed and you. The two-year period runs from their purchase date, not yours, and that date is not yet known"
               : "whether anyone owned the property between the last owner who claimed and you has not been established. Until it is, the start of the two-year period cannot be fixed — and it is not safe to assume it is your own completion date" };
  }

  /* The window itself. open is true / false / null(not derivable). */
  function fvrWindow(s){
    s = s || {};
    var st = windowStart(s);
    if(!st.derivable)
      return { start:null, deadline:null, open:null, basis:st.basis, why:st.why };
    var deadline = new Date(st.date.getTime() + TWO_YEARS_MS);
    return { start:st.date, deadline:deadline, open:(now(s) <= deadline),
             basis:st.basis, why:st.why };
  }

  /* -------------------------------------------------------------------------
     A-4 - the disposal value statement requirement, s.187A(10) and (11).

     A third clock, and the one most often already expired by the time anybody
     looks: it runs from the past owner CEASING TO OWN, not from any sale.
     HMRC's CA26482 case is exactly this - an owner who discontinued, brought
     in a disposal value without selling, and sold years later by which time
     both this period and any election were long out of time.

     Satisfied only where the statement was made within two years of cessation
     AND the client has actually obtained it (s.187A(11), and s.187B(1) which
     puts the burden of producing it on the client).
     ------------------------------------------------------------------------- */
  function dvsAssess(s){
    s = s || {};

    if(s.dvs_statement === "no")
      return { outcome:OUT.NIL, value:null,
               why:"no written statement of the disposal value was made by the earlier owner. Where the disposal value statement requirement applies and no statement exists, s.187A(3)(c) treats the expenditure on those fixtures as nil",
               action:"none available — the two-year period for making the statement runs from that owner ceasing to own the fixtures and cannot be reopened" };

    if(s.dvs_statement !== "held")
      return { outcome:OUT.INDET, value:null,
               why:"a written statement of the disposal value from the earlier owner has not been produced. The law puts the burden of showing this on you (s.187B(1)), so the bottom of the range is shown as nil until it is obtained",
               action:"obtain the disposal value statement from the earlier owner, or their advisers — conveyancing file, CPSE replies, or the seller's own computations" };

    var cess = parseDate(s.past_owner_cessation_date);
    if(!cess)
      return { outcome:OUT.INDET, value:null,
               why:"a statement has been produced, but the date the earlier owner stopped owning the fixtures is not known, so it cannot be shown that the statement was made inside the two-year period s.187A(11) allows",
               action:"establish the date that owner ceased to own the fixtures — usually the title history" };

    var made = parseDate(s.dvs_statement_date);
    if(!made)
      return { outcome:OUT.INDET, value:null,
               why:"a statement has been produced, but it is not dated, so it cannot be shown to have been made inside the two-year period s.187A(11) allows",
               action:"establish the date the statement was made" };

    if(made > new Date(cess.getTime() + TWO_YEARS_MS))
      return { outcome:OUT.NIL, value:null,
               why:"the statement was made more than two years after that owner ceased to own the fixtures. s.187A(11) requires it inside that period, so the requirement is not satisfied and s.187A(3)(c) treats the expenditure on those fixtures as nil",
               action:"none available — the period cannot be extended, and an election is not an alternative on these facts" };

    var v = (s.dvs_stated_value === 0 || s.dvs_stated_value) ? +s.dvs_stated_value : null;
    if(v === null || isNaN(v))
      return { outcome:OUT.INDET, value:null,
               why:"the statement was made in time, but the figure it states has not been captured, so the cap it sets cannot be sized",
               action:"read the disposal value off the statement" };

    return { outcome:OUT.CAP_DV, value:v,
             why:"the earlier owner made a written statement of the disposal value within two years of ceasing to own the fixtures, and you have obtained it. The requirement is satisfied and your claim on those fixtures is capped at the figure it states",
             action:null };
  }

  /* -------------------------------------------------------------------------
     F4 / row A-F12 - was a relevant apportionment made inside the period?

     Returns true, or null. NEVER false: the absence of a valid election does
     not decide the requirement against the client, because the tribunal route
     at s.187A(7)(a) and the statements route at s.187A(6)(b) both remain, and
     the second of those is defect A-2 and is not built. null therefore means
     "not settled here", and the caller falls through to the window analysis.

     Module C owns whether the document is a valid election; this only asks
     whether the answer it reached satisfies s.187A. Both CAP-ELECT and NOMINAL
     do - a nominal election is valid, and CB_ELECTION records in terms that it
     satisfies the fixed value requirement.
     ------------------------------------------------------------------------- */
  /* -----------------------------------------------------------------------
     A-3 (12921346994), switch CB_CTA.fvr_requires_past_owner_claim, B-Q4.

     THE DEFECT. s.187A(5) hangs the fixed value requirement on the past owner
     having been REQUIRED TO BRING A DISPOSAL VALUE INTO ACCOUNT under item 1,
     5 or 9 of the s.196 Table. A past owner who never claimed brings no
     disposal value into account, so on that reading the requirement never
     applies and the engine should not be running a two-year clock at all.
     Today the engine asks the fixed-value questions of anyone with an
     entitled past owner, claimed or not. Money: UNDERSTATES claims.

     Fires only on a KNOWN "they never claimed", and only where no earlier
     entitled owner sits further back who might have. Unknown leaves the
     requirement in force, in line with the rest of this module.

     THIS SAYS NOTHING ABOUT THE POOLING REQUIREMENT. s.187A(4) is a different
     subsection on different facts and the argument that an entitled owner who
     never pooled takes the claim to nil (R-B1, board item 12829984165 series)
     is untouched by this switch and is not decided here.
     ----------------------------------------------------------------------- */
  function pastOwnerBroughtNoDisposalValue(s){
    s = s || {};
    if(s.prior_owner_claimed !== "no") return false;      /* unknown never relieves */
    if(s.earlier_entitled_owner === "yes") return false;   /* someone further back might have */
    return true;
  }

  /* -------------------------------------------------------------------------
     PHASE 154a1 (line 13), 4 October 2026 — R-B1, THE POOLING REQUIREMENT
     (s.187A(4)). The harness's oldest xfail (Suite G, C1), logged by Phase 2.

     THE DEFECT. A purchase from a seller who could claim but never did got the
     whole range with no cap and no flag: the flows applied s.187A only where
     the seller was KNOWN to have claimed, and a seller who never claimed never
     pooled. Rulebook B branch C, row C1: an entitled past owner who did not
     pool, where the requirement is in force, takes the claim to NIL - for this
     buyer and every later one (s.187A(3)). Rulebook A Addendum 1, F1: this is
     asked FIRST, before the fixed value requirement, because the reason for a
     nil differs and the report must name it.

     THE READING, AND WHAT IT LEANS ON.
       - Only a seller KNOWN to have been able to claim (prior_owner_entitled
         "yes"). An unknown entitlement is unchanged here.
       - A claim is a pooling (s.202(3)), so a seller who claimed has pooled
         and the fixed value requirement takes over, as before. There is no
         separate "pooled" answer yet (Rulebook B, defect 9): "never claimed"
         is read as "never pooled".
       - The requirement is in force where the seller stopped owning the
         fixtures after April 2014 (FA 2012 Sch 10 para 13(2),
         poolingRequirementInForce). A KNOWN earlier date takes it out of force
         (branch D) and nothing changes. An UNKNOWN date leaves it in force -
         but then the answer is unresolved with nil at the bottom (row C9's
         treatment), never a firm nil, because the date could clear it.
       - Never claimed, date known and after April 2014: NIL.
       - Never claimed, date not known: INDET, nil at the bottom.
       - Claim history "not sure" or never asked: INDET, nil at the bottom
         (row C9). N4: an unknown claim history never relieves - it gets the
         same unresolved answer whether it was "not sure" or absent.
     The seller may still pool: in a tax period that began on or before the
     day it sold (s.187A(4)), which includes the period of the sale, while that
     return can be amended. The words say what would satisfy it.
     ------------------------------------------------------------------------- */
  var POOLING_WOULD_SATISFY = "This is met only if the seller put what it spent on these fixtures into its capital allowances pool in a tax period that began on or before the day it sold them to you (s.187A(4)). A seller that has not done so may still be able to, by amending its tax return for the period of the sale while that return can still be amended. Ask the seller for its replies to the standard property enquiries on capital allowances, and for the tax computation that shows the pool.";

  function poolingAssess(s){
    s = s || {};
    if(s.prior_owner_entitled !== "yes") return null;
    if(s.prior_owner_claimed === "yes") return null;
    if(regimeOff(s)) return null;
    var known = !!parseDate(s.past_owner_cessation_date);
    if(known && !poolingRequirementInForce(s)) return null;
    var di = disposalItem(s);
    if(s.prior_owner_claimed === "no" && known)
      return { outcome:OUT.NIL, item:di.item, track:TRACK.UNKNOWN, pooling:true, requirement:"POOLING",
               why:"you have told us the seller was a tax-paying business that never claimed capital allowances on these fixtures, so it never pooled what it spent on them, and it stopped owning them after April 2014, when the requirement to pool first applies. If that is right, the fixtures claim on this purchase is nil, for you and for anyone who buys from you",
               action:POOLING_WOULD_SATISFY };
    return { outcome:OUT.INDET, item:di.item, track:TRACK.UNKNOWN, pooling:true, requirement:"POOLING",
             why:(s.prior_owner_claimed === "no"
               ? "you have told us the seller was a tax-paying business that never claimed capital allowances on these fixtures, so it never pooled what it spent on them. If it stopped owning them after April 2014 the fixtures claim on this purchase is nil, and we do not yet know when it stopped owning them"
               : "the seller was a tax-paying business that could have claimed capital allowances on these fixtures, and whether it ever did, and so whether it pooled what it spent on them, is not known. If it never did, the fixtures claim on this purchase may be nil"),
             action:POOLING_WOULD_SATISFY + (known ? "" : " And tell us the date the seller stopped owning the property.") };
  }

  /* -----------------------------------------------------------------------
     A-2 (12921346993), switch CB_CTA.s187a_6b_statements_route, A-Q8.

     THE DEFECT. The engine offers two ways of satisfying the fixed value
     requirement — a joint election (s.187A(7)(b)) and a tribunal application
     (s.187A(7)(a)) — and both die when the two-year period closes. s.187A(6)(b)
     is a THIRD route, available where the person who acquired the fixtures
     from the past owner was NOT entitled to claim, and satisfied by the two
     written statements s.187A(8) describes. IT HAS NO TIME LIMIT. A closed
     window is therefore not the end of the claim. Money: UNDERSTATES claims.

     Satisfied only where BOTH facts are positively established: the owner in
     between was never able to claim, AND the client actually holds the
     statements. s.187B(1) puts the burden of producing them on the client, so
     "there probably were some" is not enough and does not relieve.
     ----------------------------------------------------------------------- */
  function statementsRoute(s){
    s = s || {};
    if(!CB_CTA.s187a_6b_statements_route)
      return { available:false, satisfied:false, why:null };
    if(s.intervening_owner_never_entitled !== "yes")
      return { available:false, satisfied:false,
               why:"the route at s.187A(6)(b) is only open where the owner in between was never able to claim, and that has not been established" };
    if(s.s187a_8_statements === "held")
      return { available:true, satisfied:true,
               why:"the owner in between was never able to claim capital allowances on these fixtures, and you hold the two written statements s.187A(8) requires. That route has no time limit, so the fixed value requirement is satisfied even though the two-year period has closed" };
    return { available:true, satisfied:false,
             why:"the owner in between was never able to claim, which opens the route at s.187A(6)(b) \u2014 and that route has no deadline. It is satisfied by two written statements under s.187A(8), which have not been produced. The burden of producing them is yours (s.187B(1)), so the bottom of the range stays at nil until they are",
             action:"obtain the two written statements under s.187A(8) \u2014 one from the owner in between and one from the owner who last claimed. There is no deadline on this route, so it remains available however long ago the sale was" };
  }

  function relevantApportionmentMade(s){
    s = s || {};
    if(s.__apportionment) return s.__apportionment(s);        /* test hook */
    if(typeof CB_ELECTION === "undefined") return null;
    if(interveningOwner(s) !== "no") return null;             /* A-1 guard */
    var el = CB_ELECTION.assess(s);
    if(el.outcome === CB_ELECTION.OUT.CAP_ELECT || el.outcome === CB_ELECTION.OUT.NOMINAL) return true;
    return null;
  }

  /* -------------------------------------------------------------------------
     assess - the decision order of the rulebook, F0 to F7, in that order and
     for the reasons the rulebook gives for the order.
     ------------------------------------------------------------------------- */
  function assess(s){
    s = s || {};

    var di = disposalItem(s);
    var pooling = poolingRequirementInForce(s);

    /* F0 - is there a past owner at all? */
    if(s.prior_owner_entitled === "no" && s.earlier_entitled_owner === "no")
      return { outcome:OUT.OFF, item:di.item, track:TRACK.UNKNOWN, pooling:pooling,
               why:"nobody in the ownership history was ever able to claim capital allowances on these fixtures, so the second-hand fixtures conditions in s.187A do not apply at all",
               action:"s.185 can still cap the claim if an earlier owner did claim — that is assessed separately" };

    if(regimeOff(s))
      return { outcome:OUT.OFF, item:di.item, track:TRACK.UNKNOWN, pooling:pooling,
               why:"the owner who last claimed had already stopped owning the fixtures before the second-hand fixtures rules came in (FA 2012 Sch 10 para 13(1)), so s.187A does not apply to this purchase",
               action:"s.185 can still cap the claim at the disposal value that owner brought into account — that is assessed separately" };

    /* F1 - PHASE 154a1 (line 13): the pooling requirement, BEFORE the fixed
       value requirement and before the A-3 switch (Rulebook A Addendum 1, F1
       before F2). A past owner who never pooled takes the claim to nil
       whichever reading of the fixed value requirement is switched on, so the
       A-3 switch cannot reach a case this decides. poolingAssess, above. */
    var pooled = poolingAssess(s);
    if(pooled) return pooled;

    /* A-3 — the fixed value requirement needs a past owner who was required to
       bring a disposal value into account. OFF by default; switch
       CB_CTA.fvr_requires_past_owner_claim, waits on B-Q4. */
    if(CB_CTA.fvr_requires_past_owner_claim && pastOwnerBroughtNoDisposalValue(s))
      return { outcome:OUT.OFF, item:di.item, track:TRACK.UNKNOWN, pooling:pooling,
               switched:"fvr_requires_past_owner_claim",
               why:"the owner before you never actually claimed capital allowances on these fixtures, so they never had to bring a disposal value into account for them. The requirement to fix the value between the two of you is a requirement about that disposal value, so on this reading it does not apply to your purchase at all",
               action:"this does NOT decide the separate question of whether that owner was required to have pooled the expenditure first (s.187A(4)) \u2014 that is assessed on its own facts. s.185 can still cap the claim if an earlier owner did claim." };


    /* F4 - has a relevant apportionment ALREADY been made? Row A-F12.
       This limb comes before the track fork on purpose. A valid joint election
       is only available on s.196 Table items 1, 5 and 9 (Rulebook C row E-A4:
       no election is available at all on items 2 and 3), so a valid election
       both places the case on the fixed value track AND satisfies it, without
       anyone having to answer how the past owner ceased to own.

       THE INTERVENING-OWNER GUARD IS THE WHOLE OF A-1 IN ONE LINE. The
       election the client holds is the one from THEIR purchase. Where someone
       sits between them and the past owner, the relevant 2 year period ran
       from that other purchase, and an election in time under s.201(1) can be
       out of time for s.187A(7) purposes - the two provisions run from
       different events and coincide only in the direct two-party case
       (Rulebook A Addendum 1, source discrepancy 3). So the election is
       allowed to settle the position only where nobody is in between. */
    if(relevantApportionmentMade(s) === true)
      return { outcome:OUT.SATIS, item:di.item, track:TRACK.FVR, pooling:pooling,
               why:"the value of the fixtures was fixed by a joint election made with the seller within the period the law allows, so the fixed value requirement is met",
               action:null };

    /* F2 / A-6 - which requirement applies. Unknown is its own answer and is
       never resolved into the fixed value track by default. */
    if(di.track === TRACK.UNKNOWN && di.switched)
      return { outcome:OUT.INDET, item:di.item, track:TRACK.UNKNOWN, pooling:pooling,
               switched:di.switched,
               why:di.why + ". The two requirements lead to different tests on different clocks and one of them returns nil, so the bottom of the range is shown as nil until this is established",
               action:di.action };
    if(di.track === TRACK.UNKNOWN)
      return { outcome:OUT.INDET, item:di.item, track:TRACK.UNKNOWN, pooling:pooling,
               why:di.why + ". The two lead to different tests on different clocks and one of them returns nil, so the bottom of the range is shown as nil until this is established",
               action:"establish how the earlier owner stopped owning the fixtures — CPSE replies, the title history, or that owner's own computations" };

    /* F6 / A-4 - the disposal value statement track. */
    if(di.track === TRACK.DVS){
      var d = dvsAssess(s);
      return { outcome:d.outcome, item:di.item, track:TRACK.DVS, pooling:pooling,
               value:d.value, why:di.why + ". " + d.why, action:d.action };
    }

    /* F3 / F4 / A-1 - the fixed value track. The window start date, not the
       client's impression of it. */
    var w = fvrWindow(s);

    if(w.open === null)
      return { outcome:OUT.INDET, item:di.item, track:TRACK.FVR, pooling:pooling, window:w,
               why:w.why + ", so it cannot yet be said whether the route to fixing the value is still open. The bottom of the range is shown as nil until it is",
               action:"obtain the title history for the property so the relevant purchase date can be established (Land Registry title register and price paid data)" };

    /* A-2 — where the statements route is open the client is told about THREE
       routes, not two, and told that one of them does not expire. A corrected
       number under wording that still says "two routes, both with a deadline"
       would send the client to act on the wrong urgency. */
    var __sr = statementsRoute(s);

    if(w.open === true){
      if(__sr.available)
        return { outcome:OUT.LIVE, item:di.item, track:TRACK.FVR, pooling:pooling, window:w,
                 switched:"s187a_6b_statements_route",
                 why:w.why + ", and that period has not yet expired — the value can still be fixed by a joint election or by an application to the tribunal before it does. There is also a third route open to you: because the owner in between was never able to claim, two written statements under s.187A(8) will satisfy the requirement, and that route has no deadline at all",
                 action:"agree a joint election or lodge a tribunal application inside the remaining period; and in parallel obtain the two written statements under s.187A(8), which stay available after the period closes" };
      return { outcome:OUT.LIVE, item:di.item, track:TRACK.FVR, pooling:pooling, window:w,
               why:w.why + ", and that period has not yet expired — the value can still be fixed by a joint election, or by an application to the tribunal made before it does",
               action:"act inside the remaining period: agree a joint election with the other party, or lodge a tribunal application before the deadline" };
    }

    /* Closed. NOT settled as nil: s.187A(6)(b) is a third satisfaction route
       with no time limit. With CB_CTA.s187a_6b_statements_route OFF — the
       default — the route is not assessed and the outcome stays INDET, exactly
       as before Phase 51: returning NIL would decide A-2 against the client
       without anyone having ruled on it. With the switch ON the route is
       assessed, and where it is satisfied it settles the requirement. */
    if(__sr.satisfied)
      return { outcome:OUT.SATIS, item:di.item, track:TRACK.FVR, pooling:pooling, window:w,
               switched:"s187a_6b_statements_route",
               why:__sr.why, action:null };

    if(__sr.available)
      return { outcome:OUT.INDET, item:di.item, track:TRACK.FVR, pooling:pooling, window:w,
               switched:"s187a_6b_statements_route",
               why:w.why + ", and that period has now closed. " + __sr.why,
               action:__sr.action };

    return { outcome:OUT.INDET, item:di.item, track:TRACK.FVR, pooling:pooling, window:w,
             why:w.why + ", and that period has now closed with nothing on record fixing the value. A further route exists under s.187A(6)(b) where the owner in between was never able to claim, and that route has no time limit — so this is not yet a settled nil, but the bottom of the range is shown as nil",
             /* PHASE 53: 'action' is rendered to the CLIENT, in the "Why a
                specialist needs to look" panel. It carried an internal board
                item number and a rulebook section reference. One string was
                doing two jobs for two audiences; 'ref' is now the internal
                one and is never rendered. The handoff is still traceable —
                it is traceable in the field built for it. */
             action:"establish whether the owner in between was able to claim, and whether the two written statements under s.187A(8) can be obtained — this needs specialist and chartered tax adviser review",
             ref:"A-2, switch CB_CTA.s187a_6b_statements_route — Rulebook A Addendum 1 Group 4; board item 12921346993" };
  }

  /* Apply the assessment to the qualifying-expenditure range. Mirrors
     CB_ELECTION.applyCap, including its convention that a conservative floor
     is expressed by dropping the bottom of the range to nil rather than by
     collapsing the figure. */
  function applyOutcome(a, lo, hi, A, flag){
    switch(a.outcome){

      case OUT.OFF:
        A && A.push("the second-hand fixtures conditions do not apply to this purchase — " + a.why);
        flag && flag("s.187A OFF — " + a.why + ". " + (a.action || ""));
        return [lo, hi];

      case OUT.SATIS:
        /* The range is already capped by CB_ELECTION and must not be touched
           again here. Only the reason is added, because "the requirement was
           satisfied" and "the requirement never applied" are different answers
           that were previously indistinguishable in the output. */
        A && A.push("the second-hand fixtures condition on fixing the value is met — " + a.why);
        return [lo, hi];

      case OUT.CAP_DV:
        A && A.push("your claim on those fixtures is capped at the disposal value the earlier owner stated");
        flag && flag("DISPOSAL VALUE STATEMENT held and in time — capped at the stated figure (s.187A(10)-(11))");
        return [Math.min(lo, a.value), Math.min(hi, a.value)];

      case OUT.NIL:
        /* PHASE 154a1 (line 13): a nil names the requirement that failed (Rulebook A Addendum 1, the report). */
        if(a.requirement === "POOLING"){
          A && A.push("the fixtures claim on this purchase is nil, because the seller never pooled what it spent on them — " + a.why);
          flag && flag("s.187A(4) POOLING REQUIREMENT NOT MET — NIL (s.187A(3)) — " + a.why + ". " + (a.action || ""));
          return [0, 0];
        }
        A && A.push("the fixtures the earlier owner disposed of are nil — " + a.why);
        flag && flag("s.187A(3)(c) NIL — " + a.why + (a.action ? " " + a.action : ""));
        return [0, 0];

      case OUT.LIVE:
        A && A.push("there is still time to fix the value of these fixtures, and the figure above assumes that gets done — " + a.why);
        flag && flag("LIVE OPPORTUNITY (s.187A(7)) — " + (a.action || ""));
        return [lo, hi];

      default: /* INDET */
        A && A.push("this cannot be settled on what is known so far, so the bottom of the range is shown as nil — " + a.why);
        flag && flag((a.requirement === "POOLING" ? "s.187A(4) POOLING POSITION UNPROVEN — " : "s.187A POSITION UNPROVEN — ")
          + a.why + (a.action ? (a.requirement === "POOLING" ? ". " : " ") + a.action : ""));
        return [0, hi];
    }
  }

  /* PHASE 157a, 6 October 2026 - THE SELLER WHOSE ENTITLEMENT IS NOT KNOWN, AND
     THE WORDS FOR ONE WHO NEVER CLAIMED (from Phase 154a1 line 13(b); Rulebook
     B sections 5 and 6). Stage 3 of four flows (care homes, dental, GP, private
     hospital; supported living has no best-case step) read "never claimed" as
     the best case whatever the seller was, and said "no prior entitlement" of
     a seller the client had called a tax-paying business.
       - Entitlement "not sure" or never asked, and no claim known (never
         claimed, "not sure" or never asked - knowing less must never give a
         better floor than knowing it never claimed): Rulebook B cannot
         tell branch B (a seller never able to claim: a full apportionment) from
         branch C (able, never pooled: nil). Undetermined, so the bottom of the
         range is nil, with a flag (N4: "not sure" and absent the same).
       - Entitlement KNOWN, never claimed: the figure is unchanged (the pooling
         requirement, applied after Stage 3, decides the C cases), and the words
         say what is actually known - including branch D, a seller that stopped
         owning between April 2012 and April 2014, and A4, before April 2012. */
  var UNKNOWN_SELLER_WORDS = "whether the seller was able to claim capital allowances on these fixtures is not yet known. If it was not, a full apportionment may be available; if it was, and it never claimed, the fixtures claim on this purchase may be nil. Until we know, the bottom of the range is nil";
  var UNKNOWN_SELLER_FLAG = "SELLER'S ENTITLEMENT NOT KNOWN, AND NO CLAIM BY IT KNOWN (Rulebook B, branches B and C): a seller never able to claim leaves a full apportionment (B1); a seller able to claim that never pooled leaves nil (C1). The bottom of the range is nil until the seller's position is established, usually from its replies to the standard property enquiries on capital allowances (CPSE)";
  function neverClaimedWords(s){
    s = s || {};
    var known = !!parseDate(s.past_owner_cessation_date);
    if(known && regimeOff(s))
      return "you have told us the seller was a tax-paying business that never claimed capital allowances on these fixtures, and it stopped owning them before April 2012, before the second-hand fixtures rules began. On the information given a full apportionment is available, subject to confirming the earlier ownership chain (s.185)";
    if(known && !poolingRequirementInForce(s))
      return "you have told us the seller was a tax-paying business that never claimed capital allowances on these fixtures, and it stopped owning them between April 2012 and April 2014, before it had to pool what it spent on them. So it brought no value into account that had to be fixed with you, and on the information given a full apportionment is available, subject to confirming the earlier ownership chain (s.185)";
    return "you have told us the seller was a tax-paying business that never claimed capital allowances on these fixtures. What that leaves depends on when it stopped owning them: after April 2014 it had to pool what it spent first, and the pooling requirement below decides it";
  }

  /* PHASE 157a, 6 October 2026 - THE CESSATION DATE COMES FIRST (from 154a1
     line 13(a)). poolingAssess reads the date the seller stopped owning, so it
     must be known before the sector's fixed-value question and the questions
     above can be hidden on a nil. It was the fourth question of the block,
     after 14po, 14pol and 14pold, and the block came after x14fvr in all five
     sectors. Each sector now asks it on its own, just before x14fvr, with the
     same cfg it gives questions(); nothing else moves, so x14fvr still comes
     before x14iv, as AF3 needs.
     A-5 - the date both FA 2012 transitionals and the A-4 clock read. */
  function cessation(cfg){
    var p = cfg.prefix, g = cfg.group, rawGate = cfg.gate;
    var flag = cfg.flag || function(){};
    return [
      {id:p+"14pod", group:g, type:"date", optional:true,
       ask:"On what date did that earlier owner stop owning the property?",
       help:"Leave it blank if you don’t know. This date does real work: it decides whether the second-hand fixtures rules apply to your purchase at all, and where a written statement of value is needed it is the date the deadline for that statement runs from. It is on the Land Registry title register.",
       /* PHASE 154a1 (line 13): the caller's own gate, never the A-3 one. This
          date also decides whether the pooling requirement is in force
          (poolingAssess), which A-3 does not touch - so a seller who never
          claimed is still asked it with that switch on. Switch off, the two
          gates are the same and the flow is unchanged. */
       showIf:rawGate,
       onSet:(s,v)=>{ s.past_owner_cessation_date=v||null;
         if(!v) flag(s,"Past owner’s cessation of ownership date not captured — the FA 2012 Sch 10 para 13(1) and 13(2) transitionals and the s.187A(11) statement deadline all run from it. Both transitionals are treated as NOT applying until it is known (A-5)"); } }
    ];
  }

  /* PHASE 157a: true only where poolingAssess gives NIL - the case the
     questions after the cessation date cannot change. */
  function poolingNil(s){
    var p = poolingAssess(s);
    return !!(p && p.outcome === OUT.NIL);
  }

  /* -------------------------------------------------------------------------
     The client-facing questions, defined once rather than five times.

     EVERY ONE OF THESE IS ANSWERABLE BY A LAY PERSON. None of them names a
     Table item, a subsection or a requirement. They ask what happened, who
     sold what to whom, and what is written on a document the client is
     holding; the statutory classification is derived above.

     cfg: { prefix, group, gate, flag }
     ------------------------------------------------------------------------- */
  function questions(cfg){
    var p = cfg.prefix, g = cfg.group, rawGate = cfg.gate;
    var flag = cfg.flag || function(){};

    /* A-3 (12921346994) — the question-flow half of the same defect. On the
       reading behind CB_CTA.fvr_requires_past_owner_claim the whole s.187A
       block is beside the point where the past owner never claimed, so it is
       not asked. With the switch OFF the gate is exactly the caller’s, which
       is today’s flow, question for question. */
    var gate = function(s){
      if(!rawGate(s)) return false;
      if(CB_CTA.fvr_requires_past_owner_claim && pastOwnerBroughtNoDisposalValue(s)) return false;
      /* PHASE 157a (from 154a1 line 13(a)): a seller KNOWN able to claim, who
         never claimed and stopped owning after April 2014, already takes the
         claim to nil (poolingAssess, F1). Nothing these questions could add
         changes that, so they are not asked. Only a NIL hides them: "not
         sure", or a date not given, leaves the position open and they are
         asked as before (N4). */
      if(poolingNil(s)) return false;
      return true;
    };
    var ivAsked = function(s){ return gate(s) && interveningOwner(s) !== "no"; };

    return [

      /* A-6 - the fork in the statute, asked as five things that can happen
         to a building. */
      {id:p+"14po", group:g, type:"single",
       ask:"How did that earlier owner — the last one who could have claimed — stop owning the fixtures?",
       help:"This decides which of two quite different sets of rules applies to your claim, and they have different deadlines. If you don’t know, say so — guessing here is worse than not knowing, and it is usually answered from the title history or the pre-contract enquiries.",
       opts:[["sold_market","They sold the property in a normal sale"],
             ["sold_undervalue","They transferred it for less than it was worth — a gift, a family or group transfer, or at a discount"],
             ["new_lease_premium","They granted a new lease to someone who paid a lump sum for it"],
             ["ceased_no_sale","They stopped owning the fixtures some other way, without selling — a lease of theirs ended, for example"],
             ["discontinued_trade","They permanently stopped trading from the property but kept it"],
             ["unsure","Not sure"]],
       showIf:gate,
       onSet:(s,v)=>{ s.past_owner_disposal_mode = (v==="unsure") ? null : v;
         if(v==="unsure") flag(s,"How the past owner ceased to own the fixtures is not established — this decides between the fixed value requirement (s.187A(5)-(9)) and the disposal value statement requirement (s.187A(10)-(11)), which are different tests on different clocks. Obtain CPSE replies / title history (A-6)");
         if(v==="sold_undervalue"||v==="ceased_no_sale"||v==="discontinued_trade") flag(s,"Disposal value statement requirement in point (s.187A(10)-(11)) — no election is available on these facts and the two-year period runs from that owner CEASING TO OWN, not from any later sale (A-4)"); } },

      {id:p+"14pol", group:g, type:"single",
       ask:"When that lease was granted, did the two of them make a joint election fixing the value of the fixtures?",
       help:"This is a specific document signed by both the landlord and the incoming tenant at the time. It is the single fact that decides which set of rules applies to the lease.",
       opts:[["yes","Yes — there was a joint election"],
             ["no","No — there was no such election"],
             ["unsure","Not sure"]],
       showIf:(s)=> gate(s) && s.past_owner_disposal_mode==="new_lease_premium",
       onSet:(s,v)=>{ s.past_owner_s183_election = (v==="unsure") ? null : v;
         if(v==="unsure") flag(s, CB_CTA.lease_premium_not_item9
           ? "Whether a s.183 election was made on the past owner’s lease is unknown — with one it is s.196 Table item 5 and the two-year period runs from the grant; without one, which Table item applies is not established (a switched position, CB_CTA.lease_premium_not_item9) (A-6)"
           : "Whether a s.183 election was made on the past owner’s lease is unknown — it decides between s.196 Table item 5 and item 9, and so which date starts the two-year period (A-6)"); } },

      {id:p+"14pold", group:g, type:"date",
       ask:"On what date was that lease granted?",
       help:"The clock for fixing the fixtures value runs from this date — not from when you bought.",
       showIf:(s)=> gate(s) && s.past_owner_disposal_mode==="new_lease_premium",
       onSet:(s,v)=>s.past_owner_lease_grant_date=v||null },

      /* A-1 - the fact that moves the clock off the client's own date. */
      {id:p+"14iv", group:g, type:"single",
       ask:"Between that earlier owner and you, did anyone else own the property?",
       help:"This matters more than it sounds. The deadline for fixing the fixtures value doesn’t run from your purchase — it runs from the purchase made by whoever bought from that earlier owner. If someone sat in between, the deadline may have come and gone before you were involved at all. Developers, charities, housing associations and property-holding companies are the usual ones.",
       opts:[["no","No — I bought directly from them"],
             ["yes","Yes — someone else owned it in between"],
             ["unsure","Not sure / I don’t know the history that far back"]],
       showIf:ivAsked,
       onSet:(s,v)=>{ s.intervening_owner = (v==="unsure") ? null : v;
         if(v!=="no") flag(s,"Intervening owner between the past owner and the client — s.187A(9) runs the two-year period from THAT purchaser’s acquisition, not the client’s. Obtain the Land Registry title register and price paid history before any window is described to the client as open (A-1)"); } },

      {id:p+"14ivd", group:g, type:"date", optional:true,
       ask:"If you know it, on what date did that in-between owner buy the property?",
       help:"Leave it blank if you don’t know — a specialist can trace it from the title history. We will not assume your own purchase date here, because on these facts it is the wrong one and assuming it would overstate what you can still do.",
       showIf:(s)=> ivAsked(s) && s.intervening_owner==="yes",
       onSet:(s,v)=>s.intervening_owner_acquisition_date=v||null },

      /* A-4 - the statement, its date and its figure. */
      {id:p+"14dvs", group:g, type:"single",
       ask:"Do you have a written statement from that earlier owner setting out the value they brought into their own tax figures for the fixtures?",
       help:"This is a specific document, not a clause in the contract and not a recollection. Where it is needed, it is the only thing that keeps the claim alive on those fixtures — without it the law treats your spend on them as nil. It is usually in the conveyancing file or with the other side’s advisers.",
       opts:[["held","Yes — I have the statement"],
             ["exists_not_held","I think there was one, but I don’t have it"],
             ["no","No statement was ever made"],
             ["unsure","Not sure"]],
       showIf:(s)=> gate(s) && disposalItem(s).track===TRACK.DVS,
       onSet:(s,v)=>{ s.dvs_statement=v;
         if(v==="exists_not_held") flag(s,"Obtain the s.187A(8)/(11) disposal value statement — conveyancing file or counterparty’s advisers. The burden of producing it is the client’s (s.187B(1)) (A-4)");
         if(v==="unsure") flag(s,"Disposal value statement position unestablished — the claim on those fixtures cannot be sized until it is (A-4)");
         if(v==="no") flag(s,"NO DISPOSAL VALUE STATEMENT — s.187A(3)(c) treats the expenditure on those fixtures as nil, and the period for making one cannot be reopened (A-4)"); } },

      {id:p+"14dvsd", group:g, type:"date",
       ask:"On what date was that statement made?",
       help:"Read it off the document. It only counts if it was made within two years of that owner ceasing to own the property — a statement made later does not satisfy the requirement, however accurate it is.",
       showIf:(s)=> gate(s) && s.dvs_statement==="held",
       onSet:(s,v)=>s.dvs_statement_date=v||null },

      {id:p+"14dvsv", group:g, type:"currency",
       ask:"What disposal value does that statement give for the fixtures?",
       help:"Read the figure off the document. Your claim on those fixtures is capped at it.",
       showIf:(s)=> gate(s) && s.dvs_statement==="held",
       onSet:(s,v)=>s.dvs_stated_value=(v===0||v)?v:null },

      /* A-2 (12921346993) — THE TWO QUESTIONS THAT ARE NOT ASKED TODAY.
         The third satisfaction route at s.187A(6)(b) turns on facts nobody is
         currently asked for, so flipping the switch without these would leave
         a route that can never fire. Both are shown ONLY when
         CB_CTA.s187a_6b_statements_route is on, so with the switch off the
         flow is unchanged, question for question. */
      {id:p+"14ivne", group:g, type:"single",
       ask:"Was that in-between owner ever able to claim capital allowances on the fixtures themselves?",
       help:"Some owners never can \u2014 a charity, a pension fund, a local authority, a housing association, or a landlord letting homes. If the owner in between was one of those, there is a route to fixing the value that has NO deadline, even if the usual two-year period has long gone.",
       opts:[["yes","Yes \u2014 they could have claimed"],
             ["no","No \u2014 they were never able to claim"],
             ["unsure","Not sure"]],
       showIf:(s)=> CB_CTA.s187a_6b_statements_route && ivAsked(s) && interveningOwner(s)!=="no",
       onSet:(s,v)=>{ s.intervening_owner_never_entitled = (v==="no") ? "yes" : (v==="yes" ? "no" : null);
         if(v==="unsure") flag(s,"Whether the in-between owner was able to claim is unknown \u2014 it decides whether the no-deadline route at s.187A(6)(b) is open, which is the only route left once the two-year period has closed (A-2)"); } },

      {id:p+"14st8", group:g, type:"single",
       ask:"Do you have written statements from BOTH of those owners about the fixtures?",
       help:"Two documents, not one: a statement from the owner who last claimed and a statement from the owner in between. Together they fix the value without an election and without a tribunal, and there is no time limit on obtaining them.",
       opts:[["held","Yes \u2014 I have both"],
             ["exists_not_held","I think they exist, but I don\u2019t have them"],
             ["no","No such statements were made"],
             ["unsure","Not sure"]],
       showIf:(s)=> CB_CTA.s187a_6b_statements_route && gate(s) && s.intervening_owner_never_entitled==="yes",
       onSet:(s,v)=>{ s.s187a_8_statements = v;
         if(v!=="held") flag(s,"Obtain the two written statements under s.187A(8) \u2014 this route has NO deadline and is the only one left once the two-year period has closed. The burden of producing them is the client\u2019s (s.187B(1)) (A-2)"); } }
    ];
  }

  return { ITEM:ITEM, TRACK:TRACK, OUT:OUT,
           disposalItem:disposalItem,
           commencementDate:commencementDate, regimeOff:regimeOff,
           poolingRequirementInForce:poolingRequirementInForce,
           interveningOwner:interveningOwner,
           windowStart:windowStart, fvrWindow:fvrWindow,
           dvsAssess:dvsAssess, relevantApportionmentMade:relevantApportionmentMade,
           pastOwnerBroughtNoDisposalValue:pastOwnerBroughtNoDisposalValue,
           poolingAssess:poolingAssess, poolingNil:poolingNil,
           UNKNOWN_SELLER_WORDS:UNKNOWN_SELLER_WORDS, UNKNOWN_SELLER_FLAG:UNKNOWN_SELLER_FLAG, neverClaimedWords:neverClaimedWords,
           statementsRoute:statementsRoute,
           assess:assess, applyOutcome:applyOutcome,
           cessation:cessation, questions:questions };
})();


/* ===========================================================================
   CB_REGISTRY — the derivation layer.  PHASE 67.

   THE RULE THIS MODULE EXISTS TO ENFORCE: never ask for something a register
   holds — ask the user to confirm it.

   The four registers were named in both journey documents 76 times before this
   module existed, and neither document DERIVED anything from them. They were
   cited as sources in the output and never used to skip a question. That is the
   whole condensation opportunity and this is where it is taken.

   WHAT THIS MODULE IS NOT. It is not a connector. Nothing here makes a network
   call, and no API key appears anywhere in this file. It is the layer that
   CONSUMES a bundle of register responses and decides, field by field, whether
   we now hold an answer good enough to put in front of the user for
   confirmation — or whether we must still ask. The connectors are the
   developer's Block C work; this is the contract they fill.

   THREE THINGS THAT ARE LOAD-BEARING AND WILL LOOK LIKE OVER-ENGINEERING:

   1. A MISSING REGISTER VALUE FALLS BACK TO ASKING, ALWAYS. It never falls back
      to a default, a mean, or a guess. That is N4 and it is also the
      non-functional requirement "integrations degrade gracefully — fall back to
      asking; never block the estimate". A register that is down costs us a
      question, not an answer.

   2. PERSONAL DATA IS CLASSIFIED BY FIELD NAME AND REFUSED BY DEFAULT. Two
      names may be retrieved and no others: the Companies House PSC name (the
      common-control test needs it) and the HMLR proprietor name where the
      proprietor is a natural person. Every other field carrying a person's name
      is E_UNCLASSIFIED_FIELD and is refused — not dropped quietly, refused, so
      that a new field appearing in a supplier's response surfaces as a failure
      rather than as a silent write. That is N2, and the fail-closed direction is
      the point of it.

      NEITHER OF THE TWO IS RETRIEVED BEFORE A SIGNED ENGAGEMENT. Phase 132c,
      15 September 2026. Condition CA2 in section 15 of the legitimate interests
      assessment: before a signed engagement, checked on the server, the list of
      persons with significant control and the title register are never called.
      Their SOURCES sit in the free tier, so the gate is on the two FIELDS, not
      the source — see `postSignature` below. Nothing refuses and nothing
      throws: before signature the field is simply not consulted.

   3. DERIVATION IS JURISDICTION-AWARE. HMLR price paid exists in England and
      Wales and nowhere else. A Scottish address does not get a wrong purchase
      price; it gets a question. CB_JURIS already knows this and this module
      asks it rather than restating it.

   ONE THING THIS MODULE DOES NOT DECIDE, AND MUST NOT. Whether the register
   calls may run at Q2 at all is a data-protection question, not an engineering
   one — see CB_REGISTRY.precondition below. The switch is off.
   =========================================================================== */
var CB_REGISTRY = (function(){

  /* -------------------------------------------------------------------------
     THE PRECONDITION, AND WHY IT IS OFF.

     The moment we run these calls on an address we are processing information
     about identifiable people — the proprietor at HM Land Registry, persons of
     significant control at Companies House. Under the condensed journey that
     happens at question 2, which is before the engagement letter exists and
     before any account has been created.

     The lawful basis for that processing is the legitimate interests
     assessment, not the engagement letter. The assessment carries a condition
     that a privacy notice be published and reachable at the point of
     collection, and that condition is recorded as unmet. Until it is met, this
     layer must not fire against a live address.

     So the layer is BUILT AND SWITCHED OFF. `enabled` is false, `derive()`
     refuses while it is false, and every question the layer would have retired
     stays asked. Turning it on is one line, and it is not ours to turn.

     This is deliberately the same shape as the ten adviser switches: the
     branch exists, is tested, and defaults to current behaviour.
     ------------------------------------------------------------------------- */
  var precondition = {
    enabled: false,
    requires: "a published privacy notice reachable from the address question, " +
              "because the legitimate-interests basis for these lookups depends on it",
    unmet:   ["privacy notice published and linked at the point of collection"]
  };

  /* -------------------------------------------------------------------------
     THE SOURCES.

     `personal` lists the fields on that source which carry a natural person's
     name. `permitted` lists the ones we are allowed to retrieve. Anything in
     `personal` and not in `permitted` is refused. The two lists are written out
     separately rather than derived from one another so that adding a field to
     the response shape cannot silently add it to the permitted set.

     `postSignature` lists the fields on that source that may be retrieved only
     after a signed engagement. Phase 132c, 15 September 2026, condition CA2 of
     the legitimate interests assessment (section 15). It is a FIELD list and
     not a `gate`, for two reasons. First, the rest of each source is free:
     at the address question `hmlr` is Price Paid (tenure, price, date) and
     `companies_house` is the company search and profile, and gating the whole
     source would stop those facts being pre-filled. Second, the back end reads
     a source's `gate` string as a LICENCE blocker (research.ts, licenceGateFor),
     so a signature value there would tell an operator we lack a licence.
     The signed engagement is the record the back end's assertSignedEngagement
     returns, handed in by the server. The engine never decides it.
     ------------------------------------------------------------------------- */
  var SOURCES = {
    homedata: {
      label:"address lookup",
      gate:null,
      fields:["uprn","address_line","postcode"],
      personal:[],
      permitted:[],
      postSignature:[]
    },
    hmlr: {
      label:"HM Land Registry",
      gate:null,
      fields:["tenure","price_paid","completion_date","proprietor_name"],
      personal:["proprietor_name"],
      permitted:["proprietor_name"],         /* N2 exception 2 */  /* numbered as the Phase 3 policy numbers it, EXCEPTION_2_HMLR_INDIVIDUAL_PROPRIETOR - corrected 14 September 2026, Phase 132 */
      postSignature:["proprietor_name"]      /* the title register - CA2, Phase 132c, 15 September 2026 */
    },
    epc: {
      label:"the EPC register",
      gate:null,
      fields:["floor_area_m2","building_type","construction_age_band",
              "heating_system","hot_water_system","lighting"],
      personal:["assessor_name"],
      permitted:[],
      postSignature:[]
    },
    cqc: {
      label:"the care regulator",
      gate:null,
      fields:["registered","service_type","regulated_activities","bed_count","provider_name"],
      personal:["registered_manager_name","nominated_individual_name"],
      permitted:[],
      postSignature:[]
    },
    companies_house: {
      label:"Companies House",
      gate:null,
      fields:["entity_type","incorporation_date","year_end","accounts_filed","psc_name"],
      personal:["psc_name","director_name","secretary_name"],
      permitted:["psc_name"],                /* N2 exception 1 */  /* numbered as the Phase 3 policy numbers it, EXCEPTION_1_PSC_COMMON_CONTROL - corrected 14 September 2026, Phase 132 */
      postSignature:["psc_name"]             /* the PSC list - CA2, Phase 132c, 15 September 2026 */
    },
    voa: {
      label:"the valuation office",
      gate:"licence",                        /* not held — see the blocker map */
      fields:["rateable_value","property_description"],
      personal:[],
      permitted:[],
      postSignature:[]
    }
  };

  /* -------------------------------------------------------------------------
     THE FIELD MAP — the condensation itself.

     `retires` names what we stop asking. `confirm` is the sentence the user
     sees instead of the question: a user correcting a pre-filled figure gives a
     better answer than one typing it from memory, and it takes a second rather
     than a minute.

     `jurisdictional` marks a field whose availability CB_JURIS decides. Those
     are checked per nation rather than assumed.
     ------------------------------------------------------------------------- */
  /* ---------------------------------------------------------------------------
     RESIDENTIAL-ONLY SOURCES. Added Phase 71, 3 September 2026, and it corrects
     an assumption the whole condensation rested on.

     HM LAND REGISTRY PRICE PAID DATA CONTAINS RESIDENTIAL PROPERTY ONLY. It is
     free, Open Government Licence, no authentication, and it holds every
     residential sale in England and Wales since 1995 — and it EXCLUDES
     COMMERCIAL PROPERTY ENTIRELY, along with transfers at other than market
     value.

     A care home, a dental practice, a GP surgery and a private hospital are all
     commercial. FOUR OF THE FIVE SECTORS ARE NOT IN THIS DATASET. The journey
     documents called purchase price and date "the single biggest one" and mapped
     it to HMLR as a free derivation; for most clients that derivation returns
     nothing at all.

     SUPPORTED LIVING IS THE EXCEPTION and often genuinely is an ordinary
     dwelling bought as an ordinary dwelling, so it keeps the free route.

     WHY THIS MATTERS MORE THAN IT LOOKS. Without this list the engine would
     query Price Paid for a care home, get nothing back, and record it as "the
     register returned nothing for this address" — indistinguishable from a
     source being down. The client is not harmed, because an unknown routes to
     capture. But the logs would show a permanent register outage that is not
     one, and nobody investigates that for six months.

     The paid answer is the HMLR TITLE REGISTER at GBP 7 per title, which does
     cover commercial and carries price paid or value stated for transfers
     registered since April 2000. It fires POST-ENGAGEMENT, on a client who has
     signed — which is the right place for the only paid call in the research
     step.
     --------------------------------------------------------------------------- */
  var RESIDENTIAL_SECTORS = ["supported_living"];

  /* -------------------------------------------------------------------------
     THE LAND REGISTRY'S OWN WORDS, AND WHY THEY SIT HERE — PHASE 146h,
     23 September 2026.

     "Our records show you paid {v} for this property. Is that right?" is a
     sentence about somebody's house, and the records are not ours. They are HM
     Land Registry's Price Paid Data, published under the Open Government
     Licence, and that licence PRESCRIBES the credit and says it must appear
     verbatim. Until this phase derive() handed the sentence out with no
     attribution at all, and nothing drew it — which is the only reason this is
     a correction rather than a breach.

     THE YEAR IS A FIXED 2021 AND IS NOT A PLACEHOLDER. HM Land Registry's own
     guidance writes the line that way whatever year you read it in, and a build
     that "helpfully" substituted the current year would be publishing a credit
     the licence does not prescribe. The line was written without it until
     Phase 146c put it back.

     IT IS COPIED HERE AND CHECKED AGAINST ITS SOURCE, rather than read from it.
     This file is a browser script and the licence register is TypeScript that
     no browser loads, so there is no import to make. What there is instead is a
     test: the back end reads BOTH — this constant through the extracted engine
     package, and LICENCES[HMLR_PPD].attribution_text — and fails if the two
     ever differ by a character. A copy nothing compares is how the year went
     missing the first time.

     ONLY THE TWO PRICE PAID FIELDS CARRY IT. `tenure` is on the same source in
     this map and is NOT given the line, because at the address question tenure
     is answered by the title register and not by Price Paid. A credit on a
     field that did not come from that dataset would be a false statement of
     origin, which is a worse fault than a missing one.
     ------------------------------------------------------------------------- */
  var HMLR_PPD_ATTRIBUTION =
    "Contains HM Land Registry data \u00a9 Crown copyright and database right 2021. " +
    "This data is licensed under the Open Government Licence v3.0.";

  function sourceCoversSector(spec, sector){
    if(!spec.residentialOnly) return true;
    if(!sector) return false;   /* unknown sector never assumes coverage */
    return RESIDENTIAL_SECTORS.indexOf(sector) !== -1;
  }

  var FIELDS = {
    price_paid: {
      source:"hmlr", jurisdictional:"price_paid", residentialOnly:true,
      retires:"when did you buy the property, and for how much",
      attribution:HMLR_PPD_ATTRIBUTION,
      confirm:"Our records show you paid {v} for this property. Is that right?" },

    completion_date: {
      source:"hmlr", jurisdictional:"price_paid", residentialOnly:true,
      retires:"the completion date that starts the two-year period",
      attribution:HMLR_PPD_ATTRIBUTION,
      confirm:"and that the sale completed on {v}?" },

    tenure: {
      source:"hmlr", jurisdictional:"tenure",
      retires:"do you own the freehold or hold a lease",
      confirm:"You hold this property {v}. Is that right?" },

    floor_area_m2: {
      source:"epc", jurisdictional:null,
      retires:"how big is the building",
      confirm:"The building is recorded as {v} m². Is that about right?" },

    construction_age_band: {
      source:"epc", jurisdictional:null,
      retires:"roughly when was the building built",
      confirm:"It was built around {v}. Is that right?" },

    building_type: {
      source:"epc", jurisdictional:null,
      retires:"what kind of building is it",
      confirm:"It is recorded as {v}." },

    service_type: {
      source:"cqc", jurisdictional:null,
      retires:"what type of care do you provide",
      confirm:"You are registered as {v}. Is that right?" },

    bed_count: {
      source:"cqc", jurisdictional:null,
      retires:"how many beds are you registered for",
      confirm:"You are registered for {v} beds. Is that right?" },

    entity_type: {
      source:"companies_house", jurisdictional:null,
      retires:"what kind of business are you",
      confirm:"You trade as {v}. Is that right?" },

    year_end: {
      source:"companies_house", jurisdictional:null,
      retires:"when is your financial year end",
      confirm:"Your year end is {v}." },

    incorporation_date: {
      source:"companies_house", jurisdictional:null,
      retires:"how long has the business been going",
      confirm:"The company was incorporated on {v}." }
  };

  /* -------------------------------------------------------------------------
     THE SECTOR IS DERIVED, NOT CHOSEN.

     This is the derivation nobody had written down, and it is the largest one:
     the regulator's service type tells us which of the five engines to run. A
     client should not be asked to self-classify into "supported living" versus
     "care home" — that distinction is the master gate of an entire module and
     getting it wrong makes every answer after it the wrong answer.

     Unknown routes to asking. It does NOT route to the commonest sector.
     ------------------------------------------------------------------------- */
  function sectorFromServiceType(t){
    if(!t) return { sector:null, derivable:false,
                    why:"no regulator registration was found for this address, so which kind of business this is must be asked" };
    var v = String(t).toLowerCase();
    if(v.indexOf("care home") !== -1 || v.indexOf("nursing home") !== -1)
      return { sector:"care_homes", derivable:true,
               why:"the regulator records this as a registered care home" };
    if(v.indexOf("supported living") !== -1 || v.indexOf("supported housing") !== -1)
      return { sector:"supported_living", derivable:true,
               why:"the regulator records this as a supported living service" };
    if(v.indexOf("dental") !== -1)
      return { sector:"dental", derivable:true,
               why:"the regulator records this as a dental practice" };
    if(v.indexOf("doctor") !== -1 || v.indexOf("gp") !== -1 || v.indexOf("primary care") !== -1)
      return { sector:"gp", derivable:true,
               why:"the regulator records this as a primary care practice" };
    if(v.indexOf("hospital") !== -1 || v.indexOf("clinic") !== -1 || v.indexOf("acute") !== -1)
      return { sector:"private_hospital", derivable:true,
               why:"the regulator records this as an independent hospital or clinic" };
    return { sector:null, derivable:false,
             why:"the regulator's service type does not map to one of the five kinds of business this tool models, so it must be asked" };
  }

  /* -------------------------------------------------------------------------
     N2 — retrieve, assert, write. If the assertion throws, the write never
     happens. Classification is by FIELD NAME. A value that happens to look
     like a name is not what this checks, and a name detector is not an
     implementation of this rule.
     ------------------------------------------------------------------------- */
  function classifyField(sourceId, field, engagement){
    var src = SOURCES[sourceId];
    if(!src) return { ok:false, code:"E_UNKNOWN_SOURCE",
                      why:"'" + sourceId + "' is not a source this layer knows about" };

    /* Personal is tested BEFORE the catalogue. Both branches refuse, so the
       order is not a security question — it is a legibility one. A field we
       have catalogued as carrying a person's name should say so, because
       "not permitted" is a policy answer a developer can escalate, whereas
       "unclassified" is a drift alarm that sends them to the supplier's
       response shape. Returning the second for the first wastes the trip. */
    if(src.personal.indexOf(field) !== -1 && src.permitted.indexOf(field) === -1)
      return { ok:false, code:"E_PERSONAL_FIELD_NOT_PERMITTED",
               why:"'" + field + "' carries a person's name and is not one of the two permitted exceptions" };

    if(src.fields.indexOf(field) === -1)
      return { ok:false, code:"E_UNCLASSIFIED_FIELD",
               why:"'" + field + "' is not a catalogued field on " + src.label +
                   " — a field we have not classified is refused, not waved through" };

    /* CA2 — Phase 132c, 15 September 2026. A permitted name that is also
       post-signature is NOT_PERMITTED_YET until a signed engagement is handed
       in: `engagement` is the record assertSignedEngagement returns on the
       server. Only `signed === true` opens it (N4): an absent record, a
       record saying false, and "not sure" or "yes" typed anywhere all leave it
       shut, and none of them throws. This is a state, not a refusal — the
       field is simply not asked of the register, which is the back end's word
       for a source waiting on a gate. */
    if((src.postSignature || []).indexOf(field) !== -1 && !(engagement && engagement.signed === true))
      return { ok:false, code:"NOT_PERMITTED_YET", postSignature:true,
               why:"'" + field + "' is retrieved from " + src.label + " only after a signed engagement, " +
                   "checked on the server — until then it is not consulted" };

    return { ok:true };
  }

  /* -------------------------------------------------------------------------
     derive() — the whole layer in one call.

     `bundle` is what the connectors returned, shaped { hmlr:{...}, epc:{...} }.
     `opts.nation` feeds the jurisdiction check. Returns, for every field in the
     map, either a derived value with its provenance or an instruction to ask.

     It refuses outright while the precondition is unmet. A refusal is not an
     error state for the journey — every question simply stays asked, which is
     exactly today's behaviour.
     ------------------------------------------------------------------------- */
  function derive(bundle, opts){
    bundle = bundle || {}; opts = opts || {};
    var nation = opts.nation || "england";
    /* Phase 71: the sector decides whether a residential-only source can answer
       at all. Absent, it is treated as unknown and never assumed to be covered. */
    var sector = opts.sector || null;
    var out = { enabled:precondition.enabled, values:{}, provenance:{},
                ask:[], refused:[], gated:[], notCovered:[], why:{} };

    if(!precondition.enabled){
      out.ask = Object.keys(FIELDS);
      out.why.__layer = "register derivation is switched off until " + precondition.requires +
                        "; every question it would have retired stays asked";
      return out;
    }

    Object.keys(FIELDS).forEach(function(f){
      var spec = FIELDS[f], srcId = spec.source, src = SOURCES[srcId];

      if(src.gate){
        out.gated.push(f);
        out.ask.push(f);
        out.why[f] = "we do not hold the licence for " + src.label + ", so this is asked";
        return;
      }

      if(spec.jurisdictional && !(CB_JURIS.sources(nation) || {})[spec.jurisdictional]){
        out.ask.push(f);
        out.why[f] = "this is not published for property in this nation, so it is asked";
        return;
      }

      /* The residential-only check. It must come BEFORE the bundle is read, or
         a commercial property with an accidental match would derive a price
         from a dataset that does not contain commercial property — which would
         be a wrong number rather than a missing one. */
      if(!sourceCoversSector(spec, sector)){
        out.ask.push(f);
        out.notCovered.push(f);
        out.why[f] = sector
          ? ("this source holds residential property only, and a " + sector.replace(/_/g," ") +
             " is commercial — so it is asked, and confirmed later from the title register")
          : "this source holds residential property only and the sector is not yet known, so it is asked";
        return;
      }

      var cls = classifyField(srcId, f);
      if(!cls.ok){ out.refused.push({field:f, code:cls.code, why:cls.why}); out.ask.push(f); return; }

      var raw = bundle[srcId];
      var v = (raw && raw[f] !== undefined && raw[f] !== null && raw[f] !== "") ? raw[f] : null;

      if(v === null){
        out.ask.push(f);
        /* PHASE 71 — the specific temptation this line exists to refuse.
           An absent Companies House match reads like "therefore a sole trader",
           and the journey documents said exactly that: "a sole trader is the
           case where nothing comes back, which is itself the answer". IT IS NOT.
           A business name that does not match is far more often a trading name,
           a slight misspelling, or a group subsidiary filed under a different
           name than it is an unincorporated business. Entity type sets the tax
           rate, the year end, the amendment window and which relief rules apply
           — guessing it makes every answer after it the answer to a different
           question. An unknown routes to capture, never to a guess. */
        out.why[f] = (srcId === "companies_house")
          ? ("nothing matched at " + src.label + " for this business — which is NOT evidence of a sole trader, " +
             "only evidence of no match, so it is asked")
          : ("nothing came back from " + src.label + " for this address, so it is asked");
        return;
      }

      out.values[f] = v;
      /* PHASE 146h: the provenance carries the publisher's prescribed credit where the field has one, so a screen
         that draws the sentence has the words beside it and cannot draw one without the other. `attribution` is
         null, never absent and never "", for a field whose source prescribes none — a reader testing for it gets
         an answer either way. */
      out.provenance[f] = { source:srcId, label:src.label,
                            attribution: spec.attribution || null,
                            confirm:spec.confirm.replace("{v}", String(v)) };
    });

    return out;
  }

  /* How many questions this layer retires, and how many it leaves. Used by the
     front door to say honestly how much was derived rather than claiming a
     figure nobody checked. */
  function retired(d){
    return Object.keys(d.values || {}).map(function(f){ return FIELDS[f].retires; });
  }

  return { precondition:precondition, SOURCES:SOURCES, FIELDS:FIELDS,
           RESIDENTIAL_SECTORS:RESIDENTIAL_SECTORS,
           HMLR_PPD_ATTRIBUTION:HMLR_PPD_ATTRIBUTION,
           sourceCoversSector:sourceCoversSector,
           classifyField:classifyField, derive:derive, retired:retired,
           sectorFromServiceType:sectorFromServiceType };
})();


/* ===========================================================================
   CB_FRONTDOOR — six questions to an indicative range.  PHASE 67.

   Replaces the front of the journey, not the engines behind it. The five sector
   engines keep every question they have; what changes is that the client no
   longer meets 50 of them before seeing a number.

   THE THREE CORRECTIONS. The front door as originally described would have lost
   valid claims in three places. All three are implemented here and none of them
   is silent — each carries the reasoning so it can be overruled on the record
   rather than reverted by accident.

   THE MOST IMPORTANT THING IN THIS MODULE IS WHAT IT DOES NOT DO. Two of the
   three corrections were ALREADY RIGHT in the engine before this phase started:

     · The April 2014 threshold is not a constant here. CB_S187A derives it as
       the regime commencement plus two years, which lands on 1 April 2014 for
       companies and 6 April 2014 for income tax payers — the split a single
       hard-coded date would have flattened.

     · The two-year clock's starting point was never hard-coded. CB_S187A
       derives it, and where an intervening owner cannot be established it
       returns "not derivable" and says in terms that it is not safe to assume
       the client's own completion date.

   So the risk this phase actually carried was not that the corrections were
   missing. It was that a new front door would REIMPLEMENT them and get them
   wrong. Every date test below therefore delegates. There is no second clock.
   =========================================================================== */
var CB_FRONTDOOR = (function(){

  /* -------------------------------------------------------------------------
     CORRECTION 1 — the "has anyone ever claimed" gate.

     As originally described this gate would turn away most of the claims we
     want, for two reasons.

     "Any tax relief" is far too broad. Nearly every trading business has
     claimed something — a repairs deduction, annual investment allowance on
     loose equipment, allowances on a van. A truthful owner reads that question
     and answers yes, and we gate out a qualifying client on a question they
     misread in our favour.

     And the one that matters: a PREVIOUS owner having claimed is normally what
     makes the current owner's claim POSSIBLE, not what kills it. For purchases
     after April 2014 the pooling requirement generally means the seller must
     have brought the fixtures into their own tax figures before the buyer can
     claim at all. A seller who claimed and then signed a joint election is the
     textbook working case. Gating on "someone claimed" rejects precisely the
     transactions that succeed.

     What actually kills a claim is that YOU have already claimed on these same
     fixtures, or that an election fixed their value at or near nil.

     So: gate on the client's own prior claim, and ask about the previous owner
     separately and without gating. "Don't know" is the honest and commonest
     answer and the engine handles it — s.187A is built to.
     ------------------------------------------------------------------------- */
  /* -------------------------------------------------------------------------
     AMENDED 3 SEPTEMBER 2026 (PHASE 71) — THIS QUESTION NO LONGER GATES AT ALL.

     Phase 67 narrowed the gate from "has anyone ever claimed" to "have YOU
     already claimed on these fixtures", which was the right correction and did
     not go far enough. Two reasons it now gates on nothing:

     ONE. Relief may still be available. A prior claim on the fixtures does not
     touch renovation spend, post-acquisition plant, or works the client has
     paid for since. Stopping the flow discards all of it.

     TWO, AND THE ONE THAT DECIDED IT. We do not know what the earlier claim
     was FOR. "A claim" in a client's mouth covers a repairs deduction, annual
     investment allowance on loose equipment, allowances on a van, and a
     genuine fixtures claim. Four different facts, one word, and only the
     fourth would matter. Gating on the word rejects clients on a question they
     misread in our favour.

     WHAT REPLACES IT. A flag to the chartered tax adviser, raised before any
     figure is finalised, plus the offer of a call. The overstatement guard at
     the document stage already routes any prior-claim signal to the CTA — this
     feeds it rather than pre-empting it.

     WHAT IS STILL ARITHMETIC RATHER THAN MARKETING. Where the client has
     themselves already claimed on THESE SAME FIXTURES there is no second claim
     on the same pound. That is not a gate we are choosing; it is one pound
     counted twice. It surfaces downstream as a reasoned negative on the
     FIXTURES ELEMENT ONLY, leaving renovation and later spend intact — which
     is why it is a flag with a scope, and not a stop.
     ------------------------------------------------------------------------- */
  function gateQ1(s){
    s = s || {};

    if(s.own_prior_claim === "yes")
      return { gated:false, code:"OWN_PRIOR_CLAIM",
               flag:"CTA_REVIEW_PRIOR_CLAIM",
               scope:"fixtures_only",
               message:"You have told us a claim has already been made on the fixtures here. That does not stop this assessment — claims are often narrower than people remember, and money spent since is a separate claim on a separate basis. One of our advisers will go through it with you.",
               offerCall:true };

    if(s.own_prior_claim === "not sure")
      return { gated:false, code:"OWN_PRIOR_CLAIM_UNSURE",
               flag:"CTA_REVIEW_PRIOR_CLAIM",
               scope:"fixtures_only",
               message:null, offerCall:true };

    /* The previous owner's claim is NOT a gate either, and never was. It is an
       input, and on the commonest answer — don't know — it is an input the
       engine is designed to carry unresolved rather than guess. */
    return { gated:false, code:null, flag:null, scope:null,
             message:null, offerCall:false };
  }

  /* -------------------------------------------------------------------------
     Q1b — THE CLAIMANT GATE, AND THE ONLY GATE LEFT IN THE FRONT DOOR.
     Added Phase 71, absorbing the old S3 and the old Q6.

     Allowances reduce a tax bill; there has to be one to reduce. That is the
     one thing in this funnel worth stopping for.

     "NOT SURE" NO LONGER TERMINATES — reversed on 3 September 2026. The
     previous specification routed it to the reasoned negative alongside "no"
     and "charity". A practice manager or an office administrator who does not
     know their company's tax position is the ORDINARY case, not the suspicious
     one, and terminating on it destroyed good leads at the third question.

     It now continues, and the figure it produces carries the condition on its
     face rather than asserting it. That keeps an unknown out of the favourable
     branch — the figure is conditional, not claimed — without pretending we
     know something we do not.
     ------------------------------------------------------------------------- */
  function gateQ1b(s){
    s = s || {};
    var v = s.is_uk_taxpayer;

    if(v === "no" || v === "charity")
      return { gated:true, code:"NO_TAX_TO_RELIEVE",
               message:"Capital allowances reduce a bill for UK income tax or corporation tax. On what you have told us there is no such bill to reduce, so there is likely little or no claim here.",
               offerCall:true, condition:null, askProfit:false };

    if(v === "yes")
      return { gated:false, code:null, message:null, offerCall:false,
               condition:null, askProfit:true };

    /* undefined, or the explicit "not sure" */
    return { gated:false, code:"TAX_STATUS_UNKNOWN",
             flag:"CONFIRM_TAX_STATUS_ON_CALL",
             message:null, offerCall:false,
             condition:"This assumes the business pays UK corporation tax or income tax. If it does not, there is no claim to make.",
             askProfit:false };
  }

  /* -------------------------------------------------------------------------
     Q1c — WHAT PROMPTED THIS. Added Phase 71.

     Selects the statutory machinery: apportionment for a purchase, invoice
     analysis for works. It also becomes the DEFAULT trigger for every property
     the client adds, which is what keeps a multi-property funnel from growing
     a question — see propertyDefaults().
     ------------------------------------------------------------------------- */
  var TRIGGERS = ["purchase", "new_build", "refurb", "fit_out"];

  function methodFor(trigger){
    return (trigger === "purchase") ? "s562_apportionment" : "invoice_analysis";
  }

  /* The spend pair a property asks for depends on ITS OWN trigger, not on the
     answer given at Q1c — a client who bought one property and built another
     has two methods and must be asked correctly on each. */
  function spendFieldsFor(trigger){
    switch(trigger){
      case "purchase":  return { amount:"purchase_price", date:"completion_date",
                                 label:"Purchase price", dateLabel:"Completion date" };
      case "new_build": return { amount:"build_cost", date:"completion_date",
                                 label:"Build cost", dateLabel:"Completed" };
      case "refurb":    return { amount:"works_cost", date:"works_year",
                                 label:"Cost of works", dateLabel:"When" };
      case "fit_out":   return { amount:"fitout_cost", date:"works_year",
                                 label:"Fit-out cost", dateLabel:"When",
                                 extra:"lease_start_year" };
      default:          return null;
    }
  }

  /* -------------------------------------------------------------------------
     THE MULTI-PROPERTY RULE, AND WHY IT COSTS NO QUESTIONS.

     Drop-off happens in the FIRST property block, not inside the repeater. A
     client who has clicked "add another property" has already opted into more
     typing; they are not the person the condensation is protecting.

     So property 1 renders NEITHER the trigger control NOR the entity control
     and inherits both silently. Properties 2+ render both PRE-ANSWERED — one
     tap to change, zero taps to accept.

     THE ENTITY NAME IS DELIBERATELY NEVER ASKED. The figure needs the entity
     TYPE, which sets the tax rate. The NAME only matters for the common-control
     test, which is post-engagement work, so the adviser resolves it on the call
     rather than the funnel carrying a field for it.
     ------------------------------------------------------------------------- */
  function propertyDefaults(index, s){
    s = s || {};
    var first = (index === 0);
    return {
      trigger:      s.trigger_default || null,
      entity_type:  first ? null : (s.entity_type_default || null),
      renderTrigger: !first,      /* property 1 inherits silently */
      renderEntity:  !first,      /* property 1 is asked outright */
      entityPrompt:  first ? null : "Held by the same entity?",
      entityDefault: first ? null : "yes"
    };
  }

  /* -------------------------------------------------------------------------
     Q3 — THE WORKS HEADING, AND THE DOUBLE-COUNT IT PREVENTS.

     Where a property's trigger was a refurbishment or a fit-out, Q2 has ALREADY
     captured that spend. Asking "any work done?" against that property invites
     the client to enter the same money a second time, and the figure inflates
     by exactly the amount they were most sure about.
     ------------------------------------------------------------------------- */
  function worksHeadingFor(trigger){
    if(trigger === "refurb" || trigger === "fit_out")
      return { heading:"Any further work since?",
               sub:(trigger === "refurb"
                    ? "You have already told us about the refurbishment above — this is anything on top of it."
                    : "You have already told us about the fit-out above — this is anything on top of it."),
               alreadyCaptured:true };
    return { heading:"Any work done to this property?", sub:null, alreadyCaptured:false };
  }

  /* -------------------------------------------------------------------------
     THE COMBINED FIGURE, AND THE HONESTY PROBLEM IN IT.

     Each property's figure is an UPPER BOUND. Adding upper bounds gives the sum
     of maxima — a total that gets LESS achievable with every property added,
     because it is the outcome in which every property simultaneously lands at
     the top of its own band. Three properties at "up to 500,000" produces "up
     to 1.5m", a number essentially nobody receives.

     This function therefore returns the breakdown ALONGSIDE the total and marks
     the total's reliability, so a caller cannot render the headline without
     having been handed the thing that qualifies it.
     ------------------------------------------------------------------------- */
  function combineCeilings(perProperty){
    perProperty = perProperty || [];
    var live = perProperty.filter(function(p){ return p && !p.terminal && typeof p.ceiling === "number"; });
    var terminal = perProperty.filter(function(p){ return p && p.terminal; });

    /* AMENDED PHASE 72. A property that is neither terminal nor numeric — the
       client left the spend blank, or answered "I don't know" — previously fell
       through both filters and VANISHED FROM THE PAGE ENTIRELY. It was not in
       the total, which was right, and it was not named anywhere, which was not:
       the client would have entered three addresses and seen two, with nothing
       saying why. An unknown routes to capture, and capture means the client is
       actually asked. */
    var unpriced = perProperty.filter(function(p){
      return p && !p.terminal && typeof p.ceiling !== "number";
    });

    return {
      total: live.reduce(function(a,p){ return a + p.ceiling; }, 0),
      breakdown: live,               /* MUST be rendered with the total */
      terminalProperties: terminal,  /* named on their own line, never suppressed */
      unpricedProperties: unpriced,  /* likewise — silence here loses a property */
      /* Every property given must appear somewhere on the screen. */
      accountedFor: live.length + terminal.length + unpriced.length,
      count: live.length,
      /* The more properties, the weaker the headline. Past a handful, the
         combined RANGE is the more defensible display and this says so. */
      headlineReliability: live.length <= 1 ? "single"
                         : live.length <= 3 ? "weakening"
                         : "prefer_range",
      breakdownRequired: true
    };
  }

  /* -------------------------------------------------------------------------
     CORRECTION 2 — the threshold is April 2014, and it is not one date.

     Delegated in full. Nothing here knows what the date is, which is the point:
     a constant in this module could drift away from the engine's, and the
     client-facing half is exactly where nobody would notice.
     ------------------------------------------------------------------------- */
  function poolingTest(s){
    s = s || {};
    var inForce = CB_S187A.poolingRequirementInForce(s);
    var commencement = CB_S187A.commencementDate(s);
    return {
      inForce: inForce,
      thresholdISO: new Date(commencement.getTime() + 2*365.25*24*60*60*1000).toISOString().slice(0,10),
      why: inForce
        ? "the property changed hands after the fixtures pooling rules came in, so what the seller did with the fixtures matters to what you can claim"
        : "the seller's ownership ended early enough that the pooling requirement does not apply to this purchase"
    };
  }

  /* -------------------------------------------------------------------------
     CORRECTION 3 — a closed window is not a nil.

     Missing the two-year window closes the ELECTION route. It does not close
     the claim. An application to the tribunal may still be open, and where the
     owner in between was never able to claim, two written statements satisfy
     the requirement with no time limit at all.

     Telling a client "you are out of time" while a route is still open is the
     most expensive error this engine could make, and it is exactly the error
     the gate as originally drafted would have produced.

     This function never returns a bare nil. Where the window has closed it
     returns the routes that remain, and where nothing can be established it
     says so rather than resolving against the client.
     ------------------------------------------------------------------------- */
  function windowOutcome(s){
    s = s || {};
    var w = CB_S187A.fvrWindow(s);
    var routes = [];

    if(w.open === true){
      routes.push("a joint election with the seller, which is the quickest route while the period is open");
      routes.push("an application to the tribunal to fix the value, if the seller will not agree");
    } else if(w.open === false){
      /* Closed. The election route has gone; these have not necessarily. */
      routes.push("an application to the tribunal, if one was lodged inside the period and is still undetermined");
      routes.push("two written statements, where the owner in between was never able to claim — a route with no time limit at all");
    } else {
      routes.push("we cannot yet fix when the period started, so no route is ruled out");
    }

    /* Renovation spend is unaffected by any of this and stands on its own.
       Saying so here is what stops a closed window reading as a nil. */
    routes.push("any renovation or fit-out spend of your own, which is a separate claim and is not affected by this at all");

    return {
      open: w.open,
      deadline: w.deadline || null,
      basis: w.basis,
      why: w.why,
      routes: routes,
      nil: false,          /* structural: this function has no nil branch */
      needsSpecialist: (w.open === false || w.open === null)
    };
  }

  /* -------------------------------------------------------------------------
     THE SIX QUESTIONS.

     `derived` names what a register would have answered had the layer been on.
     While CB_REGISTRY.precondition.enabled is false every one of these is asked
     exactly as it is today — the condensation is built, wired and switched off
     with the layer it depends on.
     ------------------------------------------------------------------------- */
  var QUESTIONS = [

    { id:"F1", type:"choice",
      ask:"Have you already made a capital allowances claim on the fixtures in this building — the plant, wiring, heating and similar?",
      help:"We mean the fixed things in the fabric of the building. Not equipment you bought and could take with you. Not ordinary repairs either. Those are different claims, and having made them does not affect this one.",
      options:["yes","no","not sure"],
      gates:true, derived:null,
      onSet:function(s,v){ s.own_prior_claim = v; } },

    { id:"F1b", type:"choice",
      ask:"Do you know whether a previous owner ever claimed on them?",
      help:"Most people don't, and that is fine — it does not stop a claim. Often it is the opposite. For purchases since April 2014, a seller who claimed is usually what makes your own claim possible.",
      options:["yes","no","don't know"],
      gates:false, derived:null,
      onSet:function(s,v){
        s.previous_owner_claimed = v;
        /* Feed the engine's own vocabulary rather than a parallel one.
           PHASE 154a1 (line 13): "no" is a seller who did not CLAIM, which is not a
           seller who could not - a tax-paying seller who never claimed is the one
           the pooling requirement takes to nil (R-B1). So "no" records the claim
           history only and leaves entitlement to its own question; it used to set
           prior_owner_entitled "no", the best case, which inverted that rule. */
        if(v === "yes") s.prior_owner_entitled = "yes";
        else if(v === "no") s.prior_owner_claimed = "no";
        /* "don't know" deliberately sets nothing — unresolved, not guessed. */
      } },

    { id:"F2", type:"contact",
      ask:"Your name, your business, and the address of the property.",
      help:"You can add more than one property. Each address is its own claim and its own set of lookups; one engagement covers all of them.",
      gates:false, derived:null,
      triggersDerivation:true,
      onSet:function(s,v){
        v = v || {};
        s.contact = { name:v.name||null, business:v.business||null,
                      email:v.email||null, phone:v.phone||null };
        s.addresses = v.addresses || (v.address ? [v.address] : []);
      } },

    { id:"F3", type:"choice",
      ask:"Have any renovations been done?",
      options:["yes","no"],
      gates:false, derived:null,
      onSet:function(s,v){ s.renovations = v; } },

    { id:"F3a", type:"choice",
      ask:"What kind of work was it?",
      options:["full renovation","cosmetic renovation","extension or expansion","other"],
      showIf:function(s){ return s && s.renovations === "yes"; },
      gates:false, derived:null,
      onSet:function(s,v){
        s.renovation_type = v;
        /* Worth saying rather than showing a nil: cosmetic work is usually a
           repair, which is immediately deductible and often BETTER for the
           client than a capital allowance — but it is not this claim. */
        s.renovation_is_probably_repair = (v === "cosmetic renovation");
      } },

    { id:"F3b", type:"currency",
      ask:"Roughly how much was spent?",
      showIf:function(s){ return s && s.renovations === "yes"; },
      gates:false, derived:null,
      onSet:function(s,v){ s.renovation_spend = (typeof v === "number" && v > 0) ? v : null; } },

    /* The addition that changes the answer rather than refining it. Renovation
       spend has its own clock, and spend before the client owned the building
       belongs to somebody else's claim. A year is enough at this stage. */
    { id:"F3c", type:"year",
      ask:"Roughly when was that work done?",
      help:"A year is enough. It matters because work done before you owned the building is not your claim to make.",
      showIf:function(s){ return s && s.renovations === "yes"; },
      gates:false, derived:null,
      onSet:function(s,v){ s.renovation_year = v || null; } },

    { id:"F4", type:"confirm",
      ask:"You bought this property on {completion_date} for {price_paid}. Is that right?",
      askFallback:"When did you buy the property, and what did you pay for it?",
      gates:false,
      derived:["completion_date","price_paid"],
      onSet:function(s,v){
        v = v || {};
        if(v.completion_date) s.acquisition_date = v.completion_date;
        if(typeof v.price_paid === "number") s.purchase_price = v.price_paid;
      } },

    { id:"F5", type:"confirm",
      ask:"You trade as {entity_type}. Is that right?",
      askFallback:"What kind of business is this — limited company, LLP, partnership or sole trader?",
      gates:false,
      derived:["entity_type","year_end"],
      onSet:function(s,v){
        v = (v && v.entity_type) ? v.entity_type : v;
        s.entity_type = v || null;
        /* This one question sets the tax rate, the year end, the amendment
           window and which reliefs apply — and Companies House hands us all
           four in the same call. A sole trader is the case where nothing comes
           back, which is itself the answer. */
        s.claimant_type = (v === "limited company") ? "company" : "individual";
      } },

    { id:"F6", type:"choice",
      ask:"How is the business doing this year?",
      help:"Only this year — we already have the last filed position. A loss-making business may be due a cash repayment rather than a smaller future bill, and that is a materially different conversation.",
      options:["profitable","loss-making","roughly break-even"],
      gates:false, derived:null,
      onSet:function(s,v){ s.current_year_position = v; } }
  ];

  /* Which of the six are answered by confirmation rather than by asking, given
     what the derivation layer actually returned. Honest by construction: with
     the layer off, this returns nothing derived and everything asked. */
  function shape(d){
    d = d || { values:{} };
    var confirmed = [], asked = [];
    QUESTIONS.forEach(function(q){
      if(!q.derived){ asked.push(q.id); return; }
      var got = q.derived.every(function(f){ return d.values && d.values[f] !== undefined; });
      (got ? confirmed : asked).push(q.id);
    });
    return { confirmed:confirmed, asked:asked, total:QUESTIONS.length };
  }

  /* AMENDED PHASE 71. Q1 no longer stops the flow; Q1b can. And the assessment
     is now per property, so readiness is per property too — a client with three
     addresses and one missing sector is not "not ready", they are ready on two
     and short of one answer on the third. Collapsing that into a single boolean
     is how a repeater ends up blocking on a property the client already
     abandoned. */
  function readyForRange(s){
    s = s || {};

    var g = gateQ1b(s);
    if(g.gated) return { ready:false, why:"no UK tax bill to relieve", code:g.code, properties:[] };

    var props = s.properties || [];
    if(!props.length)
      return { ready:false, why:"no property has been given yet", code:null, properties:[] };

    var perProperty = props.map(function(p, i){
      p = p || {};
      var need = ["address", "sector", "entity_type", "trigger"];
      var fields = spendFieldsFor(p.trigger);
      if(fields){
        /* An explicit "I don't know" IS an answer and satisfies the field. A
           null is not. That distinction is the whole of N4 in one line. */
        need = need.concat([fields.amount, fields.date]);
      }
      var missing = need.filter(function(k){ return p[k] === undefined || p[k] === null; });
      return { index:i, address:p.address || null,
               ready:missing.length === 0, missing:missing };
    });

    var notReady = perProperty.filter(function(p){ return !p.ready; });

    return {
      ready: notReady.length === 0,
      why: notReady.length ? "one or more properties are incomplete" : null,
      code: null,
      condition: g.condition,          /* the tax-status caveat, where it applies */
      properties: perProperty
    };
  }

  return { QUESTIONS:QUESTIONS, gateQ1:gateQ1, gateQ1b:gateQ1b,
           TRIGGERS:TRIGGERS, methodFor:methodFor, spendFieldsFor:spendFieldsFor,
           propertyDefaults:propertyDefaults, worksHeadingFor:worksHeadingFor,
           combineCeilings:combineCeilings,
           poolingTest:poolingTest,
           windowOutcome:windowOutcome, shape:shape, readyForRange:readyForRange };
})();


/* ===========================================================================
   CB_FEE — the fee display.  PHASE 67, basis fixed PHASE 74, rate set to a
   flat 3% PHASE 132e.

   Q55 ANSWERED 3 SEPTEMBER 2026. Lakhbir Dhillon (Head of Business Development): "The 5% is
   on the allowance." The fee is a percentage of the ALLOWANCES IDENTIFIED, not
   of the tax saved. That BASIS stands.

   THE RATE, DECIDED 15 SEPTEMBER 2026 AND BUILT 16 SEPTEMBER 2026 (PHASE 132e).
   Lakhbir Dhillon, in the answer box under "Is our fee now a flat 3% of the
   allowances identified - with no minimum and no bands?": "yes, flat fee of 3%
   of the allowances for 1 or more properties", and "A further multi-site
   discount can be applied depending on site/opportunities". So: 3% of the
   allowances identified, on every job and any number of properties, with NO
   minimum fee and NO bands. It replaces the 5% built in Phase 74.

   On a £500,000 allowance at 25% tax the two readings are now £15,000
   (allowances basis — OURS) and £3,750 (tax-saved basis — REJECTED), still a
   fourfold difference for the same job, because the ratio is 1/tax rate and
   does not depend on the fee rate. Corroborated by the Eureka competitor
   invoice (07-reference-and-benchmarks/eureka-competitor-report,
   invoice 8134/24): "Fee 4% of Capital Allowances
   Identified" — an allowances-basis fee is standard market practice.

   THE GUARD BELOW IS NOT A BASIS-UNKNOWN GUARD ANY MORE — that question is
   closed and is not to be reopened here. It is now a DATA-READINESS guard:
   render must still refuse if the allowances-identified figure for THIS case
   has not actually been computed. A fee shown against a case with no
   allowances figure yet is exactly the failure this module was built in
   Phase 67 to prevent, just with a different missing input. Do not delete or
   weaken this refusal path — change what it is computed FROM, not whether it
   checks.

   IMPORTANT — CONSUMER-PROTECTION POINT (see CB_FEE.DISCLOSURE below):
   because allowances are usually claimed gradually (writing-down allowances
   at the rate in force for each period - Rulebook I - over up to a decade) while the fee falls due at once, the fee
   can EXCEED the cash the client actually realises in tax saving in any one
   year. This is not capped. Every place this module's output reaches a
   client-facing screen or document MUST also surface DISCLOSURE, legibly, not
   as small print. See monday item 12966924106 for the (separate, larger,
   NOT done here) modelling of that gap. */
var CB_FEE = (function(){

  /* 3% of allowances identified. The basis is Q55 (3 Sep 2026); the rate is
     Lakhbir's answer read 15 Sep 2026, built 16 Sep 2026 (Phase 132e). Flat:
     no bands, no minimum fee, the same rate for one property or many. */
  var RATE = 0.03;

  /* THE MULTI-SITE DISCOUNT — DISCRETIONARY, AND NOT A NUMBER.
     Decided: "A further multi-site discount can be applied depending on
     site/opportunities". It replaces the old 5% / 10% / 15% multi-site table,
     which is gone: there are NO fixed tiers.
     NOT decided, and asked under the same question: the largest discount that
     may be given, and who approves it. Both are NAMED NULLS below and must stay
     null until Lakhbir answers. Nothing in this module reads them, and the
     quoted fee is NEVER reduced by this object automatically — a discount is
     something a person agrees with a client in writing, case by case, after
     the 3% fee has been quoted. */
  var MULTI_SITE_DISCOUNT = {
    discretionary: true,
    fixed_tiers: null,
    largest_discount: null,
    approved_by: null,
    asked: "the largest discount and who approves it",
    applied_automatically: false
  };

  function readings(allowances, taxRate){
    if(typeof allowances !== "number" || allowances <= 0) return null;
    var rate = (typeof taxRate === "number" && taxRate > 0) ? taxRate : null;
    return {
      of_allowances: allowances * RATE,   /* the basis we charge on */
      of_tax_saved: (rate === null) ? null : allowances * rate * RATE
                    /* kept only for internal comparison / the disclosure below —
                       never the amount rendered */
    };
  }

  var DISCLOSURE = "Our fee is 3% of the capital allowances identified, not 3% "+
    "of the tax you save. Allowances are usually claimed gradually — as writing-down "+
    "allowances on a reducing balance, at the rate in force for each period — over as long as a decade, "+
    "while our fee falls due at once. That means the tax you actually save in "+
    "any one year can be, and often is, less than the fee. The fee is not "+
    "capped by, and may exceed, what you save in tax in a given year.";

  /* PHASE 77 — the third argument, and what it must NOT do.
     Board item 12966924106.

     `ctx` carries whatever the caller knows about how the allowances will
     actually relieve: the pool split, the chargeable period start, the entity
     type, any first-year entitlement the engine has established, and the
     client's profits. All of it is optional. Where it is absent CB_BENEFIT
     bounds the answer rather than guessing it, so the comparison below is
     returned on EVERY call — including the refusal path, where the fee itself
     is null.

     WHAT DID NOT CHANGE, AND IS ASSERTED NOT TO HAVE:
       - the rate. 5% when this was written (Q55, Phase 74); 3% from Phase
         132e, which was Lakhbir's decision and not a change made by this
         argument.
       - the basis. Still on allowances identified, and not reopened here.
       - DISCLOSURE. Not reworded, not softened, not conditioned on the
         comparison. It is a legal-facing sentence and it applies to every
         client whether or not this one trips the arithmetic.
       - the rendered amount, while both CB_FEEGUARD switches are off — which
         is how they ship. */
  function display(allowances, taxRate, ctx){
    var r = readings(allowances, taxRate);
    var fee = r ? r.of_allowances : null;

    /* Computed unconditionally. A figure that exists is a figure someone can
       act on; a figure that does not exist forecloses the decision. */
    var comparison = CB_BENEFIT.compare(fee, CB_BENEFIT.assess({
      allowances:   allowances,
      main:         ctx && ctx.main,
      special:      ctx && ctx.special,
      tax_rate:     taxRate,
      period_start: ctx && ctx.period_start,
      is_company:   ctx && ctx.is_company,
      years:        ctx && ctx.years,
      first_year:   ctx && ctx.first_year,
      profits:      ctx && ctx.profits
    }));

    /* PHASE 153b, 4 October 2026 - Word question 59 (the director's: "Once we
       charge VAT, should the fee comparison include VAT for clients who cannot
       reclaim it?") and question 226. The no-claim test's VAT rule (Phase
       151b, below) carried into this comparison, behind its own switch,
       CB_FEEGUARD.fee_comparison_counts_vat, and DORMANT WHILE WE ARE NOT
       VAT-REGISTERED: until we are, the comparison is returned exactly as it
       was, whichever way the switch sits. The client's VAT position on our fee
       is the caller's ctx.client_vat where it gives one, otherwise what the
       session's works-VAT answer can tell us (clientVatFromWorks, below). */
    var clientVat = (ctx && ctx.client_vat) || (ctx && ctx.session ? clientVatFromWorks(ctx.session) : null);
    comparison = withFeeVat(comparison, fee, ctx, taxRate, allowances, clientVat);

    if(!r){
      /* PHASE 113d. The gate is assessed here too, and it comes back
         UNDETERMINED naming expected_fee — which is N4 exactly: a case whose
         allowances have not been computed has no fee to test, and a gate that
         "passed" it would be relieving on an unknown. */
      return { render:false, amount:null,
               reason:"the allowances identified for this case have not been computed yet. Nothing is quoted until they are.",
               readings:null, disclosure:DISCLOSURE,
               comparison:comparison, warning:null,
               capped:false, uncapped_amount:null,
               gate:CB_GATE.assess({ fee:null, sector:ctx && ctx.sector }),
               recommendation_threshold:recommendationThreshold(null, comparison, false, clientVat) };
    }

    /* Switch (a). Caps ONLY where the benefit model is determined: capping
       against a bounded range would be choosing a number out of that range on
       the client's behalf, in whichever direction suited us. */
    var amount = r.of_allowances, capped = false, uncapped = null;
    if(CB_FEEGUARD.fee_cap_at_year_one_benefit && comparison.computed &&
       comparison.determined && comparison.fee_exceeds_year_one_benefit === true){
      uncapped = amount;
      amount = comparison.year_one_benefit;
      /* Phase 153b: where VAT on our fee is counted (the client cannot reclaim
         it), the cap is the fee whose VAT-inclusive cost is the year-one
         benefit, so the client is not capped at a figure plus VAT. */
      if(comparison.fee_vat && comparison.fee_vat.treatment === "COUNTED_CLIENT_CANNOT_RECLAIM" && comparison.fee_vat.vat_rate)
        amount = Math.round(comparison.year_one_benefit / (1 + comparison.fee_vat.vat_rate) * 100) / 100;
      capped = true;
    }

    /* Switch (b). Adds a sentence. Touches the amount by nothing. */
    var warn = CB_FEEGUARD.fee_warn_when_exceeds_benefit
                 ? CB_BENEFIT.warning(comparison) : null;

    /* PHASE 113d — THE ENGAGEMENT GATE. Assessed on `amount` rather than on
       r.of_allowances, because the gate tests the fee that would ACTUALLY go
       out: if switch (a) above ever caps the fee, the capped figure is what
       the client would be quoted and therefore what has to clear the line.
       With switch (a) off, as shipped, the two are the same number.

       COMPUTED UNCONDITIONALLY, ACTED ON ONLY WHEN SWITCHED ON. Same rule as
       the benefit comparison above it: a figure that exists is a figure
       someone can act on the day the decision lands. */
    var gate = CB_GATE.assess({ fee:amount, sector:ctx && ctx.sector });

    /* PHASE 132e — THE NO-CLAIM THRESHOLD. Assessed on `amount`, the fee that
       would actually be quoted, for the gate's reason above. It adds a report
       and changes nothing else: not the amount, not render, not the reason.
       PHASE 151b (question 61): ctx.client_vat, the client's VAT position on
       our fee ("can_reclaim" / "cannot_reclaim"; anything else is not known),
       is handed on so the test can count VAT where it must. It is data the
       caller passes, not a question on the screen; see NO_CLAIM_VAT below. */
    var threshold = recommendationThreshold(amount, comparison, gate.withholds_quote, clientVat);

    if(gate.withholds_quote){
      /* The one behavioural change the switch buys. No figure is rendered;
         the readings are still returned because they are internal and the
         operator pricing the job by hand needs them. */
      return { render:false, amount:null, reason:CB_GATE.COME_BACK,
               readings:r, disclosure:DISCLOSURE, comparison:comparison,
               warning:warn, capped:capped, uncapped_amount:uncapped,
               gate:gate, recommendation_threshold:threshold };
    }

    return { render:true, amount:amount, reason:null, readings:r,
             disclosure:DISCLOSURE, comparison:comparison,
             warning:warn, capped:capped, uncapped_amount:uncapped,
             gate:gate, recommendation_threshold:threshold };
  }

  /* ---------------------------------------------------------------------------
     THE NO-CLAIM THRESHOLD — "below the recommendation threshold".  PHASE 132e.

     DECIDED. Lakhbir Dhillon, in the answer box under "Below what size of claim
     do we advise a client not to claim at all?", read 15 September 2026, built
     16 September 2026: the threshold is about the CLIENT'S benefit only; it is
     £1,000 of tax relief to the client after our fee; and the client still
     chooses, with the figures in front of them.

     WHICH RELIEF FIGURE, AND WHY. "Tax relief after our fee" is read as the
     engine's CUMULATIVE tax relief over its modelling horizon
     (CB_BENEFIT's cumulative_benefit, five years) minus the fee. Year-one
     relief was rejected because a claim relieves over many years and a
     year-one test would tell almost every client on writing-down allowances
     not to claim, which is the fee-versus-benefit timing point and not a
     question of size. Lifetime relief (allowances x rate) was rejected
     because the engine does not model it year by year and it ignores the
     profits constraint. The five-year figure is the largest figure the engine
     actually determines. THIS READING IS FOR THE TAX ADVISER TO CONFIRM.

     THREE THINGS IT NEVER DOES. It refuses no work, withholds no quote and
     moves no figure: render, amount and reason are decided above it, exactly
     as before. It is advice with the figures shown, and the choice stays the
     client's.

     UNKNOWN IS NOT A BRANCH (N4). It fires ONLY where the benefit model is
     DETERMINED: one scenario, a relief figure that is a number, and a fee that
     is a number. A tax rate answered "not sure" and a tax rate never given
     both leave the benefit unmodelled and come back UNDETERMINED by the same
     line of code; a pool split that is not known leaves a RANGE, which is also
     UNDETERMINED. An unknown relief is never read as nil relief, so an unknown
     never tells a client not to claim.

     THE WORDING IS AWAITING THE TAX ADVISER'S REVIEW, and says so in its own
     metadata (awaiting_tax_adviser_review). No report carrying it issues
     before that review.
     --------------------------------------------------------------------------- */
  var NO_CLAIM_THRESHOLD = {
    relief_after_fee_below: 1000,
    relief_basis: "cumulative_benefit",
    decided_by: "Lakhbir Dhillon",
    decision_read: "2026-09-15",
    built: "2026-09-16",
    awaiting_tax_adviser_review: true
  };

  /* ---------------------------------------------------------------------------
     VAT IN THE NO-CLAIM TEST.  PHASE 151b, 25 September 2026.  Word question 61.

     DECIDED. Lakhbir Dhillon, question 61 "For the £1,000 no-claim test, do we
     count five years of relief, and include VAT?", closed 24 September 2026:
     "The relief is calculated over the 5 years – and must include VAT". Closed
     as: measure the relief over five years, and include VAT where the client
     cannot reclaim it. The tax adviser reviews the wording.

     FIVE YEARS WAS ALREADY THE MEASURE AND IS NOT TOUCHED HERE. Phase 132e read
     "tax relief after our fee" as CB_BENEFIT's cumulative_benefit, whose
     horizon is CB_BENEFIT.HORIZON = 5 (above, "THE NO-CLAIM THRESHOLD"). The
     answer to question 61 confirms that reading; nothing below changes it.

     WHAT VAT IS COUNTED, AND ONLY THEN. VAT is on OUR FEE, and it exists only
     once WE are VAT-registered. So the fee counted in the no-claim test is:
       - we are NOT registered (today): the fee. There is no VAT to count, and
         the client's own VAT position does not matter. The test behaves
         exactly as it did before this phase, byte for byte.
       - we ARE registered and the client CANNOT reclaim VAT: the fee plus VAT
         at vat_rate, to the penny. That VAT is a real cost to the client, so
         it comes off their relief with the fee.
       - we ARE registered and the client CAN reclaim VAT: the fee alone. VAT
         the client gets back is not a cost to them.
       - we ARE registered and the client's VAT position is NOT KNOWN: no
         figure. The test comes back UNDETERMINED with a plain reason, exactly
         as an unknown tax rate or pool split does above.

     UNKNOWN IS NOT A BRANCH (N4), AGAIN. The client's VAT position reaches this
     module as `ctx.client_vat` and only two values are known: "can_reclaim" and
     "cannot_reclaim". "not sure", an absent key, null, "" and anything else
     (a partial-exemption "mixed" included — how much of our VAT such a client
     recovers is itself not known) all take ONE line of code to "not_known", so
     they give identical reports. Not known is never read as "can reclaim" (that
     would count no VAT and make the relief look bigger) and never read as
     "cannot reclaim" (that would count VAT the client may get back and could
     tell them not to claim on a guess). Nor is a registered flag with no usable
     rate read as a rate of nil: that too is UNDETERMINED.

     THE CLIENT'S VAT POSITION IS DATA THE CALLER PASSES, NOT A NEW QUESTION.
     The five flows already ask whether VAT on the SPENDING can be reclaimed
     (care homes Q18, dental D18, supported living S18, GP G19). That is a
     question about the client's capital spend, and whether its answer can
     stand for VAT on OUR FEE is a tax reading this phase does not make: it is
     not wired, and it is for the tax adviser. Until it is, `ctx.client_vat`
     is passed by whoever calls CB_FEE.display, and a caller that passes
     nothing gets "not known" - which, while we are not registered, changes
     nothing at all.

     THE RATE IS DATA. 20% is the UK standard rate of VAT (GOV.UK, "VAT rates").
     The back end keeps its own dated VAT_RATE finance setting for invoices; on
     the day we register, the two are set together.

     THE SENTENCES BELOW THAT MENTION VAT ARE NEW CLIENT-FACING WORDING AND ARE
     AWAITING THE TAX ADVISER'S REVIEW, as NO_CLAIM_THRESHOLD's are, and say so
     in their own metadata (awaiting_tax_adviser_review). While we are not
     registered none of them can be printed.
     --------------------------------------------------------------------------- */
  var NO_CLAIM_VAT = {
    we_are_vat_registered: false,      /* the back end's VAT_NOTE: "Cap Rebate is not VAT registered" */
    vat_rate: 0.20,                    /* UK standard rate, GOV.UK "VAT rates" */
    client_positions: ["can_reclaim", "cannot_reclaim"],   /* anything else is not known */
    counted_when: "we are VAT-registered and the client cannot reclaim VAT",
    decided_by: "Lakhbir Dhillon",
    question: 61,
    decision_read: "2026-09-24",
    built: "2026-09-25",
    awaiting_tax_adviser_review: true
  };

  /* The VAT the no-claim test counts on `fee`, and why. One line decides the
     client's position; every value that is not one of the two known ones is
     "not_known", so "not sure" and absent cannot come apart. */
  function vatInNoClaim(fee, clientVat){
    var cfg = NO_CLAIM_VAT;
    var position = (clientVat === "can_reclaim" || clientVat === "cannot_reclaim") ? clientVat : "not_known";
    var feeKnown = typeof fee === "number" && isFinite(fee);
    var registered = cfg.we_are_vat_registered === true;
    var rateKnown = typeof cfg.vat_rate === "number" && isFinite(cfg.vat_rate) && cfg.vat_rate > 0;
    var out = { we_are_vat_registered: registered, vat_rate: registered && rateKnown ? cfg.vat_rate : null,
                client_vat_position: position, treatment: null, known: true, vat: null, why: null,
                awaiting_tax_adviser_review: cfg.awaiting_tax_adviser_review };
    if(!registered){
      out.treatment = "NOT_REGISTERED_NO_VAT";
      out.vat = feeKnown ? 0 : null;
    } else if(!rateKnown){
      out.treatment = "UNDETERMINED"; out.known = false;
      out.why = "we are VAT-registered but no VAT rate is set, so the VAT on our fee cannot be worked out and is never treated as nil";
    } else if(position === "cannot_reclaim"){
      out.treatment = "COUNTED_CLIENT_CANNOT_RECLAIM";
      out.vat = feeKnown ? Math.round(fee * cfg.vat_rate * 100) / 100 : null;
    } else if(position === "can_reclaim"){
      out.treatment = "NOT_COUNTED_CLIENT_CAN_RECLAIM";
      out.vat = feeKnown ? 0 : null;
    } else {
      out.treatment = "UNDETERMINED"; out.known = false;
      out.why = "we do not know whether you can reclaim the VAT on our fee, so the relief after our fee and its VAT " +
                "cannot be worked out. It is not guessed either way, and we do not tell you not to claim";
    }
    return out;
  }

  /* PHASE 153b, 4 October 2026 - Word question 226 ("Can a client's answer
     about VAT on their building work tell us whether they can reclaim VAT on
     our fee?"). Our recommendation, for the tax adviser to check: only where
     the business that paid for the works is the one we would invoice and its
     VAT position has not changed (works_vat_same_business, asked only once we
     are VAT-registered). Then "Reclaimed in full" means it can reclaim VAT on
     our fee and "Not reclaimable (exempt)" means it cannot. Every other answer
     - partly, mixed, dispensing, zero-rated, not sure, none - and every case
     without that confirmation stays NOT KNOWN (null), which the no-claim test
     and the comparison treat as not known (N4). */
  function clientVatFromWorks(s){
    if(!s || s.works_vat_same_business !== true) return null;
    if(s.works_vat === "reclaim") return "can_reclaim";
    if(s.works_vat === "exempt") return "cannot_reclaim";
    return null;
  }

  /* PHASE 153b, 4 October 2026 - VAT IN THE FEE-VERSUS-BENEFIT COMPARISON
     (Word question 59, for the director). The same rule as the no-claim test
     (vatInNoClaim): VAT on our fee is counted only where we are VAT-registered
     and the client cannot reclaim it; a client who can is compared on the fee
     alone; a client whose position is not known gets no verdict unless the
     comparison comes out the same with and without the VAT (N4). Not
     registered (today), or the switch off: the comparison is returned
     untouched - not one field added. Where it acts it adds fee_vat (the
     vatInNoClaim report) and fee_counted, and `fee` stays the fee before VAT. */
  function withFeeVat(c, fee, ctx, taxRate, allowances, clientVat){
    if(!c || c.computed !== true) return c;
    if(CB_FEEGUARD.fee_comparison_counts_vat !== true) return c;
    var v = vatInNoClaim(fee, clientVat);
    if(v.treatment === "NOT_REGISTERED_NO_VAT") return c;
    var assessed = function(){ return CB_BENEFIT.assess({
      allowances: allowances, main: ctx && ctx.main, special: ctx && ctx.special, tax_rate: taxRate,
      period_start: ctx && ctx.period_start, is_company: ctx && ctx.is_company, years: ctx && ctx.years,
      first_year: ctx && ctx.first_year, profits: ctx && ctx.profits }); };
    var out;
    if(v.treatment === "COUNTED_CLIENT_CANNOT_RECLAIM" && typeof v.vat === "number"){
      out = CB_BENEFIT.compare(fee + v.vat, assessed());
      out.fee = c.fee; out.fee_counted = fee + v.vat;
    } else if(v.treatment === "NOT_COUNTED_CLIENT_CAN_RECLAIM"){
      out = c; out.fee_counted = c.fee;
    } else {
      /* Not known (or a registered flag with no usable rate): the verdicts
         stand only where the fee alone and the fee with VAT agree. */
      var rate = NO_CLAIM_VAT.vat_rate;
      var withVat = (typeof rate === "number" && isFinite(rate) && rate > 0 && typeof fee === "number")
        ? CB_BENEFIT.compare(Math.round(fee * (1 + rate) * 100) / 100, assessed()) : null;
      out = c;
      ["fee_exceeds_year_one_benefit", "fee_exceeds_cumulative_benefit"].forEach(function(k){
        if(!withVat || withVat[k] !== c[k]) out[k] = null; });
      out.fee_to_year_one_benefit = null; out.fee_to_cumulative_benefit = null;
      out.fee_counted = null;
    }
    out.fee_vat = v;
    return out;
  }

  function recommendationThreshold(fee, comparison, quoteWithheld, clientVat){
    var c = comparison || {};
    var line = NO_CLAIM_THRESHOLD.relief_after_fee_below;
    var feeKnown = typeof fee === "number" && isFinite(fee);
    var reliefKnown = c.computed === true && c.determined === true &&
                      typeof c.cumulative_benefit === "number" && isFinite(c.cumulative_benefit);
    /* PHASE 151b — the VAT on our fee, where there is any to count (above). */
    var v = vatInNoClaim(fee, clientVat);
    var determined = feeKnown && reliefKnown && v.known;
    var relief = reliefKnown ? c.cumulative_benefit : null;
    var counted = (feeKnown && v.known) ? fee + v.vat : null;
    var after = determined ? relief - counted : null;
    var fires = determined && after < line;

    function gbp(n){ return (n < 0 ? "-" : "") + "£" + Math.round(Math.abs(n)).toLocaleString("en-GB"); }

    /* The fee as the message states it. Unchanged wherever no VAT is in play,
       which is every case while we are not registered. The two VAT clauses are
       NEW CLIENT-FACING WORDING, AWAITING THE TAX ADVISER'S REVIEW (Phase 151b). */
    var feeWords = gbp(fee);
    var afterWords = "after our fee";
    if(v.treatment === "COUNTED_CLIENT_CANNOT_RECLAIM" && feeKnown){
      feeWords = gbp(fee) + " plus VAT of " + gbp(v.vat) + ", which you cannot reclaim, so " + gbp(counted) + " in all";
      afterWords = "after our fee and its VAT";
    } else if(v.treatment === "NOT_COUNTED_CLIENT_CAN_RECLAIM" && feeKnown){
      feeWords = gbp(fee) + " plus VAT, which you can reclaim and so is not counted here";
    }

    var message = null;
    if(fires && !quoteWithheld){
      message = "On these figures the tax relief to you over the first " + c.horizon_years +
        " years is about " + gbp(relief) + ", our fee is " + feeWords + ", and the relief left " +
        afterWords + " is " + gbp(after) + ". That is below " + gbp(line) + ", so we would " +
        "not normally recommend making this claim. The choice is yours: we will still " +
        "do the work if you want to go ahead.";
    }

    return {
      outcome: !determined ? "UNDETERMINED" : (fires ? "BELOW_THRESHOLD" : "AT_OR_ABOVE_THRESHOLD"),
      determined: determined,
      fires: fires,
      why: !determined
        ? (!feeKnown ? "there is no fee for this case yet, so the relief after our fee cannot be worked out"
                     : !reliefKnown ? "the tax relief for this case is not known exactly, so it is not compared with the threshold and is never treated as nil"
                                    : v.why)
        : null,
      threshold: line,
      relief: relief,
      relief_basis: NO_CLAIM_THRESHOLD.relief_basis,
      horizon_years: reliefKnown ? c.horizon_years : null,
      fee: feeKnown ? fee : null,
      /* PHASE 151b. `fee` above stays the fee before VAT, as every caller has
         read it since Phase 132e; `fee_counted` is what the test took off the
         relief (the fee, plus VAT only where it is counted), and `vat` says
         how VAT was treated and why. */
      fee_counted: counted,
      vat: v,
      relief_after_fee: after,
      /* Printed only where a quote is shown. Where the engagement gate has
         withheld the quote the fee is not printed here either; the outcome
         and the figures above are still returned for the person pricing it. */
      message: message,
      refuses_work: false,
      withholds_quote: false,
      moves_figure: false,
      client_chooses: true,
      awaiting_tax_adviser_review: NO_CLAIM_THRESHOLD.awaiting_tax_adviser_review
    };
  }

  return { RATE:RATE, readings:readings, display:display, DISCLOSURE:DISCLOSURE,
           MULTI_SITE_DISCOUNT:MULTI_SITE_DISCOUNT,
           NO_CLAIM_THRESHOLD:NO_CLAIM_THRESHOLD,
           NO_CLAIM_VAT:NO_CLAIM_VAT,
           recommendationThreshold:recommendationThreshold,
           clientVatFromWorks:clientVatFromWorks };
})();


/* ---------------------------------------------------------------------------
   CB_FEEGUARD - the two switches the fee-versus-benefit comparison waits on.
   PHASE 77, board item 12966924106. Built on the CB_CTA pattern above.

   WHAT THE COMPARISON FOUND, AND WHY IT IS NOT MINE TO ACT ON

   The fee is 3% of allowances identified (Q55 for the basis, Phase 74; the
   flat 3% rate from Phase 132e) and the disclosure attached to it says the fee
   "is not capped by, and may exceed, what you save in tax in a given year".
   That sentence was written as a general warning. On the one real competitor
   file we can see - Eureka invoice 8134/24, allowances identified GBP 73,740 -
   it is arithmetic. This finding was written at 5%, and at 5% the headline
   figures put the client out of pocket in year one (fee GBP 3,687.00 against
   GBP 3,405.36 of year-one relief, short by GBP 281.64). Re-derived at 3% in
   Phase 132e the HEADLINE finding reverses:

     our fee, 3% of 73,740                                  GBP 2,212.20
     tax relieved in year one (18%/6% WDA at a 40% rate)     GBP 3,405.36
                                                            ------------
     on headline figures the client is ahead in year one by GBP 1,193.16

   but the profits constraint still bites. The real client's letting profits
   were GBP 2,525, so of the GBP 8,513 of allowance available in year one only
   part could be used and the rest became a loss carried forward: year one
   actually relieved GBP 1,010.00, against which a 3% fee of GBP 2,212.20 still
   exceeds the year-one cash by GBP 1,202.20. The competitor reported a
   realised saving across two years of GBP 2,509.80 against their own fee of
   GBP 3,539.52 including VAT. So the exposure is real on this file, and it is
   a profits question rather than a headline-rate one.

   THREE THINGS COULD BE DONE ABOUT THAT AND ALL THREE ARE SOMEBODY ELSE'S CALL:
     (a) CAP the fee at the year-one benefit             -> fee_cap_at_year_one_benefit
     (b) WARN, case by case, and proceed                 -> fee_warn_when_exceeds_benefit
     (c) ADJUST THE PERCENTAGE for the case. Lakhbir confirmed when the rate
         was 5% that it is a variable sales discusses with the client; the 3%
         decision adds a discretionary multi-site discount whose largest size
         and approver are not yet decided (CB_FEE.MULTI_SITE_DISCOUNT). This
         option needs no switch - it needs a NUMBER. The comparison computes
         it: breakeven_fee_rate_year_one is the percentage at which the fee
         stops exceeding the year-one benefit on this client's facts. On the
         Eureka case on headline figures that number is 4.62%, which is above
         3%; on its real profits it is 1.37%.

   BOTH SWITCHES BELOW ARE OFF AND NEITHER IS MINE TO TURN ON. With both off,
   the rendered fee and the disclosure are exactly what shipped before this
   phase. What changed is that the comparison is now COMPUTED AND RETURNED on
   every call, switch or no switch, so the moment a decision lands the number
   is already there for whoever renders it. Raised for decision as Q90.
   --------------------------------------------------------------------------- */
var CB_FEEGUARD = {

  /* Q90(a). ON => the rendered fee is the LOWER of the fee and the tax the
     client is modelled to actually relieve in year one, and the uncapped
     figure is kept alongside it so the discount is visible rather than silent.
     Only ever caps where the benefit model is DETERMINED - capping against a
     bounded range would be picking a number out of a range on the client's
     behalf, in the direction that suits us to be seen doing.
     ON => our revenue falls on exactly the clients who can least afford it,
     which is the point of it and also the reason it is not a build decision. */
  fee_cap_at_year_one_benefit: false,

  /* Q90(b). ON => a second, CASE-SPECIFIC sentence is attached alongside the
     standing disclosure wherever the comparison says the fee exceeds the
     year-one benefit. It changes the amount by nothing.
     The standing DISCLOSURE is NOT replaced, reworded or softened by this
     switch and must not be: it is a legal-facing sentence and it applies to
     every client whether or not this particular one trips the comparison. */
  fee_warn_when_exceeds_benefit: false,

  /* Word question 59 - PHASE 153b, 4 October 2026. For the director, who asks
     the accountant. ON => once we are VAT-registered, the fee-versus-benefit
     comparison counts VAT on our fee where the client cannot reclaim it, as
     the no-claim test already does (CB_FEE.withFeeVat). It does NOTHING while
     we are not registered, on or off. Off is today's comparison: the fee
     alone. A funnel switch like the two above, not a CB_CTA tax switch. */
  fee_comparison_counts_vat: false
};


/* ---------------------------------------------------------------------------
   CB_BENEFIT - what the client actually gets back, and when.
   PHASE 77, board item 12966924106.

   THE DEFECT THIS CLOSES. The fee module computed what we charge and attached
   a sentence conceding that it may exceed what the client saves. Nothing
   anywhere computed what the client saves. So the sentence could never be
   checked against a case: it was equally true, and equally uninformative, on a
   client for whom it was wildly wrong and on a client for whom it was exact.
   A disclosure nobody can evaluate is a disclaimer, not a disclosure.

   WHAT IT DOES. Writes down the allowances year by year at the rates the
   engine already holds, applies the client's marginal rate, and reports the
   tax relieved in year one and cumulatively over a five-year horizon.

   FOUR RULES IT IS BUILT ON.

   1. NO RATE IS RESTATED HERE. Every rate comes from CB_RATES - the WDA rates,
      the 2026 main-pool change and its CA23222 straddle hybrid, and the
      first-year reliefs. Rulebook I rule 7.1, and LEG-E1's whole point.

   2. UNKNOWN IS BOUNDED, NEVER GUESSED. Three facts change the answer and are
      routinely absent: the main/special pool split (CB_POOL refuses to guess
      it and so does this), the chargeable period start (which decides 18% or
      14% on the main pool), and, where AIA is in play, which pool it is
      allocated against (Rulebook I question I-Q5, open). Where one is unknown
      this module runs the scenarios AT BOTH ENDS and returns a RANGE. It never
      picks a midpoint, and the fee-exceeds-benefit boolean stays null unless
      every scenario in the range agrees.

   3. NO ENTITLEMENT IS INVENTED. AIA, full expensing and the two first-year
      allowances change year one enormously - full expensing takes a main-pool
      figure from 14% relieved to 100% relieved - which is exactly why they are
      not applied unless the caller passes an entitlement that the engine has
      actually established. reliefsEstablished() below reads the session and,
      on every case the shipped question set can currently produce, returns
      nothing established and names the fact that is missing. That is not a
      stub. It is the true answer, and it is a finding: see NOT-ESTABLISHED
      below.

   4. THE PROFITS CONSTRAINT IS MODELLED WHERE IT IS KNOWN AND DECLARED WHERE
      IT IS NOT. An allowance only relieves tax against profits. Where per-year
      profits are supplied the model uses them and carries the excess forward
      as a loss; where they are not, it relieves in full and says so in the
      assumptions. The unconstrained figure is the OPTIMISTIC one, so a fee
      that already exceeds it exceeds the real benefit by more.

   NOT-ESTABLISHED - A FINDING, NOT A GAP IN THIS MODULE.

   CB_CASH gate 2 reads s.aia_headroom and understands exactly three values:
   "none", "unsure" and undefined. Nothing anywhere sets it to a headroom
   AMOUNT, and no question in any of the five sector flows asks for one. The
   same is true of s.sufficient_profit, which gate 1 reads. So the two facts
   that would let this module apply AIA, or constrain relief to profits, are
   read by the engine and captured by nothing. Raised as Q91.

   Until they are captured, the honest model on every real case is
   writing-down allowances only, unconstrained by profits - which is the
   OPTIMISTIC end. The machinery below is built, exercised by the harness and
   correct; it is waiting on two questions, not on code.
   --------------------------------------------------------------------------- */
var CB_BENEFIT = (function(){

  var HORIZON = 5;            /* five years, per the modelling brief */
  var MONTHS_IN_PERIOD = 12;

  function isNum(v){ return typeof v === "number" && isFinite(v); }
  function pos(v){ return isNum(v) && v > 0 ? v : 0; }

  /* ---- chargeable periods ------------------------------------------------
     A 12-month period from startISO. Real periods are not always 12 months and
     CB_RATES.hybridMainRate takes the actual dates, so nothing here assumes a
     12-month period is correct for a given client - it is the modelling
     assumption, and assess() declares it as one. */
  function endOf(startISO){
    var d = new Date(startISO + "T00:00:00Z");
    if(isNaN(d.getTime())) return null;
    d.setUTCMonth(d.getUTCMonth() + MONTHS_IN_PERIOD);
    d.setUTCDate(d.getUTCDate() - 1);
    return d.toISOString().slice(0, 10);
  }
  function nextStart(startISO){
    var d = new Date(startISO + "T00:00:00Z");
    if(isNaN(d.getTime())) return null;
    d.setUTCMonth(d.getUTCMonth() + MONTHS_IN_PERIOD);
    return d.toISOString().slice(0, 10);
  }

  /* ---- what the engine has actually established --------------------------
     Reads ONLY facts the shipped engine already carries. Every branch that
     would ADD a first-year relief requires an affirmative known value; an
     absent or "unsure" fact leaves the relief off and names itself. This is
     the same discipline CB_S187A calls "unknown is not a branch", pointed the
     other way: there, unknown never relieves the client of a restriction;
     here, unknown never grants an acceleration. */
  function reliefsEstablished(s, dom){
    s = s || {};
    var out = { aia:0, aia_to:null, full_expensing:false, fya_special:false,
                fya_new:false, established:[], missing:[] };

    /* Nothing accelerates a claim that cannot reach an open return at all.
       The engine already says so in its own speed narrative. */
    if(s.return_in_time !== true){
      out.missing.push("the return is not established as open, so no first-year relief is modelled - the relief still stands, it arrives as writing-down allowances");
      return out;
    }

    /* AIA. CB_CASH gate 2 is the only reader of aia_headroom in the engine and
       it recognises "none" and "unsure" and nothing else. A numeric headroom is
       what would switch AIA on here, and no question captures one - Q91. */
    if(s.aia_headroom === "none" || s.aia_used_elsewhere === "yes"){
      out.missing.push("no Annual Investment Allowance headroom is left this period, so none is modelled");
    } else if(isNum(s.aia_headroom) && s.aia_headroom > 0){
      out.aia = Math.min(s.aia_headroom, CB_RATES.FIRST_YEAR.aia_limit);
      out.aia_to = (s.aia_allocation === "special_first" || s.aia_allocation === "main_first")
                     ? s.aia_allocation : null;
      out.established.push("Annual Investment Allowance headroom of " + out.aia + " stated for this period");
      if(out.aia_to === null)
        out.missing.push("which pool the AIA is allocated against is not stated - Rulebook I question I-Q5 is open, so both orderings are modelled and the answer comes back as a range");
    } else {
      out.missing.push("Annual Investment Allowance headroom for this period has not been captured - no question asks for it (Q91), so no AIA is modelled and the figure below is the slower of the two possibilities");
    }

    /* Full expensing and the 50% FYA. Companies only, NEW plant only. The
       engine's own speed narrative already states that a second-hand purchase
       cannot use full expensing; this is that sentence made computable. */
    var isCompany = s.claimant_type === "company";
    var secondHand = (dom === "purchase");
    if(secondHand){
      out.missing.push("a second-hand purchase cannot use full expensing or a first-year allowance - the fixtures are not new and unused");
    } else if(!isCompany){
      out.missing.push("full expensing and the 50% special-rate allowance are companies only");
    } else if(s.new_and_unused !== true){
      out.missing.push("the plant has not been established as new and unused, which both full expensing and the first-year allowances require");
    } else {
      out.full_expensing = true;
      out.fya_special = true;
      out.established.push("company spend on new and unused plant - full expensing on the main-rate element and the 50% allowance on the special-rate element");
    }

    /* The s.45U 40% allowance. Main-rate only, new and unused only, and the
       expenditure must ACTUALLY have been incurred on or after 1 January 2026 -
       the s.12 deeming is disapplied for this test (CA23195A, Rulebook G
       finding G-11). Unincorporated claimants get this one and not the two
       above, which is the point most likely to be got wrong in a partnership
       claim (Rulebook I question I-Q1). */
    if(!secondHand && s.new_and_unused === true && typeof s.expenditure_incurred === "string" &&
       s.expenditure_incurred >= CB_RATES.FYA_NEW_FROM){
      out.fya_new = true;
      out.established.push("expenditure actually incurred on or after " + CB_RATES.FYA_NEW_FROM +
                           " on new main-rate plant - the s.45U 40% first-year allowance");
    }

    return out;
  }

  /* ---- one deterministic schedule ---------------------------------------
     Everything here is decided before it is called. assess() is the thing that
     decides what to do about the unknowns. */
  function schedule(o){
    var years   = o.years || HORIZON;
    var rate    = o.tax_rate;
    var isCo    = !!o.is_company;
    var profits = o.profits || null;
    var fy      = o.first_year || {};

    var mainLeft = pos(o.main), srLeft = pos(o.special);
    var totalExpenditure = mainLeft + srLeft;

    /* Year-one first-year reliefs, applied to the expenditure before any of it
       reaches a pool. Order matters: AIA is allocable and is taken first
       because the taxpayer chooses where to put it (CA23084); what survives it
       is then offered to the reliefs that are tied to one pool. */
    var fyRelieved = 0;
    var deferMain = 0, deferSr = 0;   /* balances that reach a pool from period 2 */
    var applied = [];

    var aia = Math.min(pos(fy.aia), CB_RATES.FIRST_YEAR.aia_limit);
    if(aia > 0){
      var order = (fy.aia_to === "main_first") ? ["main", "special"] : ["special", "main"];
      for(var k = 0; k < order.length && aia > 0; k++){
        if(order[k] === "special"){
          var takeS = Math.min(aia, srLeft);
          srLeft -= takeS; aia -= takeS; fyRelieved += takeS * CB_RATES.FIRST_YEAR.aia;
          if(takeS > 0) applied.push("AIA " + takeS + " against special-rate expenditure");
        } else {
          var takeM = Math.min(aia, mainLeft);
          mainLeft -= takeM; aia -= takeM; fyRelieved += takeM * CB_RATES.FIRST_YEAR.aia;
          if(takeM > 0) applied.push("AIA " + takeM + " against main-rate expenditure");
        }
      }
    }

    if(fy.full_expensing && mainLeft > 0){
      fyRelieved += mainLeft * CB_RATES.FIRST_YEAR.full_expensing;
      applied.push("full expensing on " + mainLeft + " of main-rate plant");
      mainLeft = 0;
    } else if(fy.fya_new && mainLeft > 0){
      /* 40% now; the remaining 60% gets writing-down allowances FROM THE NEXT
         chargeable period, not this one (Rulebook I section 3.1). */
      var f40 = mainLeft * CB_RATES.FIRST_YEAR.fya_new;
      fyRelieved += f40;
      deferMain += mainLeft - f40;
      applied.push("s.45U 40% first-year allowance on " + mainLeft + " of main-rate plant");
      mainLeft = 0;
    }

    if(fy.fya_special && srLeft > 0){
      var f50 = srLeft * CB_RATES.FIRST_YEAR.fya_special;
      fyRelieved += f50;
      deferSr += srLeft - f50;
      applied.push("50% first-year allowance on " + srLeft + " of special-rate plant");
      srLeft = 0;
    }

    var mainPool = mainLeft, srPool = srLeft;
    var rows = [], lossBf = 0, cumulative = 0, cumulativeAllowance = 0;
    var pStart = o.period_start || null;

    for(var i = 0; i < years; i++){
      if(i === 1){ mainPool += deferMain; srPool += deferSr; }

      var pEnd = pStart ? endOf(pStart) : null;
      var mRate = (pStart && pEnd) ? CB_RATES.hybridMainRate(pStart, pEnd, isCo) : o.main_wda_rate;
      if(!isNum(mRate)) mRate = o.main_wda_rate;
      var sRate = CB_RATES.WDA.special;

      var mWda = mainPool * mRate, sWda = srPool * sRate;
      mainPool -= mWda; srPool -= sWda;

      var allowance = (i === 0 ? fyRelieved : 0) + mWda + sWda;
      var available = allowance + lossBf;
      var used, lossCf;
      if(profits && isNum(profits[i])){
        var p = Math.max(0, profits[i]);
        used = Math.min(available, p);
        lossCf = available - used;
      } else {
        used = available; lossCf = 0;
      }
      lossBf = lossCf;

      var relief = used * rate;
      cumulative += relief;
      cumulativeAllowance += allowance;

      rows.push({
        year: i + 1,
        period_start: pStart, period_end: pEnd,
        main_wda_rate: mRate, special_wda_rate: sRate,
        first_year_allowance: (i === 0 ? fyRelieved : 0),
        main_wda: mWda, special_wda: sWda,
        allowance: allowance,
        relieved: used, loss_carried_forward: lossCf,
        relief: relief,
        main_pool_cf: mainPool, special_pool_cf: srPool
      });

      if(pStart) pStart = nextStart(pStart);
    }

    return {
      rows: rows,
      expenditure: totalExpenditure,
      first_year_reliefs_applied: applied,
      year_one_benefit: rows.length ? rows[0].relief : null,
      cumulative_benefit: cumulative,
      cumulative_allowance: cumulativeAllowance,
      horizon_years: years
    };
  }

  /* ---- the scenario builder ---------------------------------------------
     One scenario where every fact is known; two, four or eight where they are
     not. The RANGE is the honest output of an unknown, and it is the reason
     this module can answer on a case that has never seen a surveyor. */
  function assess(input){
    input = input || {};
    var rate = input.tax_rate;
    if(!isNum(rate) || rate <= 0)
      return { modelled:false, why:"no marginal tax rate for this client - the entity type and, in Scotland, the band decide it", scenarios:[] };

    var haveSplit = isNum(input.main) && isNum(input.special) && (input.main + input.special) > 0;
    var total = haveSplit ? (input.main + input.special)
                          : (isNum(input.allowances) ? input.allowances : null);
    if(!isNum(total) || total <= 0)
      return { modelled:false, why:"the allowances identified for this case have not been computed yet", scenarios:[] };

    var years = input.years || HORIZON;
    var unknowns = [], assumptions = [];

    /* dimension 1 - the pool split */
    var splits;
    if(haveSplit){
      splits = [{ label:null, main:input.main, special:input.special }];
    } else {
      splits = [{ label:"all main-rate (fastest relief)",    main:total, special:0 },
                { label:"all special-rate (slowest relief)", main:0,     special:total }];
      unknowns.push("the main/special-rate pool split is not determined, so the answer is bounded by the two extremes rather than guessed - the same refusal CB_POOL makes");
    }

    /* dimension 2 - the main-pool WDA rate, which the period start decides */
    var rates;
    if(typeof input.period_start === "string" &&
       !isNaN(new Date(input.period_start + "T00:00:00Z").getTime())){
      rates = [{ label:null, period_start:input.period_start, main_wda_rate:null }];
      assumptions.push("periods are modelled as 12 months from " + input.period_start +
                       "; the main-pool rate for each is taken from the rate table, including the straddle hybrid where a period crosses the 2026 change");
    } else {
      rates = [{ label:"pre-2026 main rate",  period_start:null, main_wda_rate:CB_RATES.WDA.main_2012_to_2026 },
               { label:"from-2026 main rate", period_start:null, main_wda_rate:CB_RATES.WDA.main_from_2026 }];
      unknowns.push("the chargeable period start is not known, so the main-pool rate could be either side of the 2026 change and both are modelled");
    }

    /* dimension 3 - where an available AIA is allocated (Rulebook I I-Q5) */
    var fyIn = input.first_year || {};
    var allocations;
    if(pos(fyIn.aia) > 0 && fyIn.aia_to !== "main_first" && fyIn.aia_to !== "special_first"){
      allocations = [{ label:"AIA to special-rate first", aia_to:"special_first" },
                     { label:"AIA to main-rate first",    aia_to:"main_first" }];
      unknowns.push("which pool the Annual Investment Allowance is set against is not stated - Rulebook I question I-Q5 is open, so both orderings are modelled");
    } else {
      allocations = [{ label:null, aia_to:fyIn.aia_to || "special_first" }];
    }

    if(!input.profits)
      assumptions.push("relief is modelled as taken in full each year - there is no profits figure for this client, so nothing is deferred as a loss. Where profits are lower than the allowance the real benefit arrives later and is smaller in year one than shown");

    var scenarios = [];
    for(var a = 0; a < splits.length; a++)
      for(var b = 0; b < rates.length; b++)
        for(var c = 0; c < allocations.length; c++){
          var fy = {
            aia: pos(fyIn.aia), aia_to: allocations[c].aia_to,
            full_expensing: !!fyIn.full_expensing,
            fya_special: !!fyIn.fya_special,
            fya_new: !!fyIn.fya_new
          };
          var sc = schedule({
            main: splits[a].main, special: splits[a].special,
            tax_rate: rate, years: years, is_company: !!input.is_company,
            period_start: rates[b].period_start, main_wda_rate: rates[b].main_wda_rate,
            first_year: fy, profits: input.profits || null
          });
          sc.label = [splits[a].label, rates[b].label, allocations[c].label]
                       .filter(function(x){ return !!x; }).join(", ") || "determined";
          scenarios.push(sc);
        }

    var y1 = scenarios.map(function(s){ return s.year_one_benefit; });
    var cu = scenarios.map(function(s){ return s.cumulative_benefit; });
    var determined = scenarios.length === 1;

    return {
      modelled: true, why: null,
      determined: determined,
      allowances: total,
      tax_rate: rate,
      horizon_years: years,
      scenarios: scenarios,
      year_one_benefit:   determined ? y1[0] : null,
      cumulative_benefit: determined ? cu[0] : null,
      year_one_benefit_range:   [Math.min.apply(null, y1), Math.max.apply(null, y1)],
      cumulative_benefit_range: [Math.min.apply(null, cu), Math.max.apply(null, cu)],
      unknowns: unknowns,
      assumptions: assumptions
    };
  }

  /* ---- the comparison ----------------------------------------------------
     Returned on every fee call whether or not any switch is on, and returned
     with computed:false and a reason where it cannot be computed, because a
     field that is sometimes absent altogether is a field no caller will build
     against.

     THE BOOLEAN IS DELIBERATELY THREE-VALUED. true where the fee exceeds the
     year-one benefit on EVERY scenario in the range, false where it exceeds it
     on none, null where the range straddles - because on a case where the
     answer depends on a fact nobody has established, "true" and "false" are
     both assertions we have not earned. */
  function compare(fee, a){
    if(!a || !a.modelled)
      return { computed:false, why:(a && a.why) || "no benefit model for this case",
               determined:false, fee:(isNum(fee) ? fee : null), allowances:null,
               horizon_years:null,
               year_one_benefit:null, cumulative_benefit:null,
               year_one_benefit_range:null, cumulative_benefit_range:null,
               fee_to_year_one_benefit:null, fee_to_cumulative_benefit:null,
               fee_to_year_one_benefit_range:null, fee_to_cumulative_benefit_range:null,
               fee_exceeds_year_one_benefit:null, fee_exceeds_cumulative_benefit:null,
               breakeven_fee_rate_year_one:null, breakeven_fee_rate_cumulative:null,
               breakeven_fee_rate_year_one_range:null,
               breakeven_fee_rate_cumulative_range:null,
               unknowns:[], assumptions:[] };

    var y1lo = a.year_one_benefit_range[0], y1hi = a.year_one_benefit_range[1];
    var culo = a.cumulative_benefit_range[0], cuhi = a.cumulative_benefit_range[1];

    function ratio(f, v){ return (isNum(v) && v > 0 && isNum(f)) ? f / v : null; }
    function verdict(f, lo, hi){
      if(!isNum(f)) return null;
      if(f > hi)  return true;     /* exceeds even the most favourable scenario */
      if(f <= lo) return false;    /* exceeds none of them */
      return null;                 /* the range straddles - not ours to call */
    }

    return {
      computed: true, why: null,
      determined: a.determined,
      fee: fee,
      allowances: a.allowances,
      horizon_years: a.horizon_years,

      year_one_benefit: a.year_one_benefit,
      cumulative_benefit: a.cumulative_benefit,
      year_one_benefit_range: a.year_one_benefit_range,
      cumulative_benefit_range: a.cumulative_benefit_range,

      fee_to_year_one_benefit:   a.determined ? ratio(fee, a.year_one_benefit)   : null,
      fee_to_cumulative_benefit: a.determined ? ratio(fee, a.cumulative_benefit) : null,
      fee_to_year_one_benefit_range:   [ratio(fee, y1hi), ratio(fee, y1lo)],
      fee_to_cumulative_benefit_range: [ratio(fee, cuhi), ratio(fee, culo)],

      fee_exceeds_year_one_benefit:   verdict(fee, y1lo, y1hi),
      fee_exceeds_cumulative_benefit: verdict(fee, culo, cuhi),

      /* The third option, and the one Lakhbir has already said is live: the fee
         rate (3% from Phase 132e, with a discretionary multi-site discount) is
         a variable sales discusses with the client. This is the rate at
         which the fee stops exceeding the benefit on THIS client's facts. It
         decides nothing - it is the number the decision needs. */
      breakeven_fee_rate_year_one:   a.determined ? ratio(a.year_one_benefit, a.allowances)   : null,
      breakeven_fee_rate_cumulative: a.determined ? ratio(a.cumulative_benefit, a.allowances) : null,
      breakeven_fee_rate_year_one_range:   [ratio(y1lo, a.allowances), ratio(y1hi, a.allowances)],
      breakeven_fee_rate_cumulative_range: [ratio(culo, a.allowances), ratio(cuhi, a.allowances)],

      unknowns: a.unknowns,
      assumptions: a.assumptions
    };
  }

  /* The case-specific sentence, held here rather than in the fee module so
     that the standing disclosure stays the one sentence it has always been.
     Only ever reached when CB_FEEGUARD.fee_warn_when_exceeds_benefit is on. */
  function warning(c){
    if(!c || !c.computed || c.fee_exceeds_year_one_benefit !== true) return null;
    return "On the figures for this property our fee is more than the tax you "+
           "would actually save in the first year. The allowances are not lost "+
           "— they carry on relieving tax in later years — but the fee "+
           "falls due now, so across five years you would be ahead and in year "+
           "one you would not.";
  }

  return { HORIZON:HORIZON, schedule:schedule, assess:assess, compare:compare,
           warning:warning, reliefsEstablished:reliefsEstablished,
           endOf:endOf, nextStart:nextStart };
})();



/* ===========================================================================
   CB_GATE_CONFIG and CB_GATE — the engagement gate.  PHASE 113d.
   Board item 13005159647.

   WHAT IT IS. Four documents on this board specify a control that refuses to
   issue an automatic quote when the expected fee would not cover what the job
   costs us, and routes instead to "we will come back to you with a price":

     the minimum-fee options paper, S9      the sentence itself
     the minimum-fee research, S7.3         two requirements the others omit
     the business plan, S6                  specified into the intake journey,
                                            and NOT YET DECIDED
     the rate card, S3 step 5 floor 2       a precondition of a fee going out

   Until this module it was implemented NOWHERE, and a pricing panel on this
   very page claimed it existed until Phase 112 removed the claim.

   WHY IT IS NOT A REFINEMENT ANY MORE. On the superseded fee base the per-
   sector minimum caught almost every small job. When the fee was 5% of the
   allowances identified (Q55) a year-one loss band sat just ABOVE each
   sector's minimum-fee crossover, where no minimum could see it. From Phase
   132e there is NO minimum fee at all - the fee is a flat 3% of the
   allowances identified (Lakhbir, answer read 15 September 2026) - so there
   is no floor under ANY small job, and every job whose 3% fee is below its
   loaded cost loses money. This gate is now the only mechanism that reaches
   any of them. The quotes it stops at 120 jobs a year and at 25 are
   re-derived from phase9/caprebate-job-economics.cjs, not restated here.

   IT TESTS THE FEE, NEVER THE PURCHASE PRICE, and the reason has changed.
   The old reason was that claimant type moved the threshold; it does not, and
   on the decided base the claimant's tax rate does not enter our fee at all.
   The reason now is that the loaded cost varies 2.2 times across the sectors
   and by more than that with annual volume, and only a fee-side test tracks
   both. There is no purchase price anywhere in this module's inputs.

   THERE IS NO COST MODEL IN HERE, AND THERE MUST NEVER BE ONE. The arithmetic
   is 04-phase-work/phase9/caprebate-job-economics.cjs, which was built and
   tested before this gate existed. This module is a DECISION LAYER over it:
   the costing is INJECTED as a function, and Suite T of the regression harness
   wires the real module in and asserts the gate's threshold is that module's
   output rather than a copy of it. A second calculator here would drift from
   that one and be wrong in whichever direction suited whoever touched it last.
   =========================================================================== */

/* ---------------------------------------------------------------------------
   CB_GATE_CONFIG — the switch, and the three inputs the gate cannot invent.
   Built on the CB_CTA / CB_FEEGUARD pattern: built, tested, and shipped OFF.
   SWITCHED ON BY PHASE 132e (16 September 2026) on Lakhbir's decision, with
   the volume he gave. It is a FUNNEL switch - it decides whether a quote is
   given automatically - and not an engine tax switch: it moves no tax figure
   and is not one of the CB_CTA switches the extraction verifier counts.
   --------------------------------------------------------------------------- */
var CB_GATE_CONFIG = {

  /* WHETHER THE GATE FIRES AT ALL WAS A COMMERCIAL DECISION, AND IT IS MADE.
     Lakhbir Dhillon, in the answer box under "Do we switch the engagement gate
     on - and how many jobs are we actually going to do this year?": (a) "Yes",
     (b) "120". Answer read 15 September 2026; built 16 September 2026.
     ON => a fee below the line returns the routing outcome instead of a
     figure. OFF was this page's behaviour before; Suite T still proves what
     off does, field by field, by flipping it. */
  enabled: true,

  requires: "Decided. Lakhbir Dhillon switched the gate on and gave 120 jobs "+
    "this year (answer read 15 September 2026, built 16 September 2026, "+
    "Phase 132e). 120 is about five to seven times the business plan's own "+
    "volume (16 jobs in year one; the papers use 25), and the gate lets more "+
    "small jobs through at 120 than it would at 25. STILL AN ESTIMATE: the "+
    "loaded cost is computed on the GBP 60,000 overhead placeholder and on "+
    "estimated, not quoted, surveyor and tax adviser fees, and every answer "+
    "the gate gives says so (cost_basis_is_a_placeholder). The gate also needs "+
    "its costing injected by whatever runs it: on this page it has none, so it "+
    "is UNDETERMINED on every case and refuses nothing.",

  /* S7.3, FIRST REQUIREMENT: ONE config value naming the delivery scenario we
     are ACTUALLY running, rather than a cost hard-coded at the point of use.
     When the section 7.2 step-down fires — a surveyor has signed a desk pack
     with material changes only, the measured surveyor cost is at or below
     GBP 750 across three jobs, and CTA involvement has run at one job in four
     across eight — this becomes "DESK_ONLY" and the gate moves with it HERE,
     in one place, and nowhere else.
     Today it is S1, surveyor-led, because that is what we will actually be
     running: the desktop pack's judgement sections are deliberately empty
     pending a surveyor's correction pass. */
  delivery_scenario: "SURVEYOR_VISIT",

  /* S7.3, SECOND REQUIREMENT: the CURRENT YEAR'S ACTUAL job volume.
     SUPPLIED BY LAKHBIR: 120 (answer read 15 September 2026). It was a named
     null until then, and it was never defaulted to 100.
     THE WARNING THAT KEPT IT NULL STILL APPLIES TO THE NUMBER GIVEN. At 25
     jobs a year the dental loaded cost is GBP 5,390; at 120 it is GBP 3,490.
     If the year's real volume falls short of 120, this line passes jobs that
     lose money at the volume actually done. Change it here, in one place, when
     the count is known. Removing it (null, or anything that is not a positive
     number, "not sure" included) makes the gate UNDETERMINED again - never
     optimistic. */
  jobs_per_year: 120,

  /* The 25% of "loaded cost plus a 25% target margin". Restated from
     phase9/caprebate-job-economics.cjs GATE.target_margin because this page
     cannot require that file; Suite T asserts the two are equal. */
  target_margin: 0.25,

  /* THE COSTING, INJECTED. A function (sector, scenario, jobsPerYear) that
     returns {known:true, loaded:<number>} or {known:false, parameter:<string>}.
     phase9/caprebate-job-economics.cjs exports costingForGate() with exactly
     that contract. It is null on this page because the page has no back office
     and makes no calls at all — with it null the gate is UNDETERMINED, which
     is honest, rather than falling back to a number invented here. */
  costing: null
};

var CB_GATE = (function(){

  /* The sentence the four documents specify, character for character. It is
     not a message about an error and must not be reworded into one: the client
     is being told a person will price the job, which is true. */
  var COME_BACK = "we will come back to you with a price";

  var OUTCOMES = {
    PASS:         "the expected fee covers the loaded cost plus the target margin",
    FIRE:         "the expected fee is below the loaded cost plus the target margin",
    UNDETERMINED: "at least one input is not known, so the gate neither passes nor fires"
  };

  function num(v){ return typeof v === "number" && isFinite(v); }

  /* -------------------------------------------------------------------------
     assess(input) — input carries ONLY {fee, sector}. Everything else comes
     from CB_GATE_CONFIG, which is the point of S7.3's "one config value".

     THE SHAPE IS THE SAME ON EVERY PATH. Every field is present on every
     return, null where it is not known. Phase 77 learned this the expensive
     way: a field that is sometimes simply absent is one no caller builds
     against, and the refusal path is exactly where a caller most needs it.
     ----------------------------------------------------------------------- */
  function assess(input){
    var i = input || {}, cfg = CB_GATE_CONFIG, missing = [];

    /* (1) THE FEE. N4 lives here and it is one line: a fee is usable only if
       it is a positive number. "not sure" is a string and is not a number;
       undefined is not a number; null is not a number. THERE IS DELIBERATELY
       NO SPECIAL CASE FOR THE "not sure" STRING — the whole defect N4 names is
       code that handles the answer it was shown and not the answer it was
       never given, so the two must travel the SAME line of code, not two lines
       that happen to agree today. */
    var fee = (num(i.fee) && i.fee > 0) ? i.fee : null;
    if(fee === null) missing.push("expected_fee");

    /* (2) THE SECTOR. Loaded cost varies 2.2x across the five, so a gate that
       did not know the sector would be guessing which cost base to use. */
    var sector = (typeof i.sector === "string" && i.sector) ? i.sector : null;
    if(sector === null) missing.push("sector");

    /* (3) THE VOLUME. Never defaulted. See the config note above. */
    var volume = (num(cfg.jobs_per_year) && cfg.jobs_per_year > 0)
                   ? cfg.jobs_per_year : null;
    if(volume === null) missing.push("jobs_per_year");

    /* (4) THE SCENARIO. */
    var scenario = (typeof cfg.delivery_scenario === "string" && cfg.delivery_scenario)
                   ? cfg.delivery_scenario : null;
    if(scenario === null) missing.push("delivery_scenario");

    /* (5) THE MARGIN. */
    var margin = (num(cfg.target_margin) && cfg.target_margin >= 0 &&
                  cfg.target_margin < 1) ? cfg.target_margin : null;
    if(margin === null) missing.push("target_margin");

    /* (6) THE COSTING. Injected, never computed here. */
    if(typeof cfg.costing !== "function") missing.push("costing");

    /* The cost is only asked for once everything it needs is present, so a
       costing function is never handed a null to interpret. */
    var loaded = null, cost = null;
    if(missing.length === 0){
      cost = cfg.costing(sector, scenario, volume);
      if(cost && cost.known === true && num(cost.loaded) && cost.loaded > 0){
        loaded = cost.loaded;
      } else {
        missing.push((cost && cost.parameter) ? cost.parameter : "loaded_cost");
      }
    }

    var determined = missing.length === 0;
    var threshold = determined ? loaded * (1 + margin) : null;

    /* FIRE and PASS are the only two determined outcomes, and the comparison
       is the whole of the decision. Everything above this line is about
       whether we are entitled to make it. */
    var outcome = !determined ? "UNDETERMINED"
                : (fee < threshold ? "FIRE" : "PASS");

    return {
      outcome: outcome,
      determined: determined,
      why: OUTCOMES[outcome],

      /* Which input stopped it, for an operator reading one line, and all of
         them, so the ordering of the checks above hides nothing. */
      parameter: determined ? null : missing[0],
      missing: missing,

      expected_fee: fee,
      loaded_cost: loaded,
      threshold: threshold,
      shortfall: (determined && outcome === "FIRE") ? threshold - fee : null,

      sector: sector,
      delivery_scenario: scenario,
      jobs_per_year: volume,
      target_margin: margin,

      /* CARRIED FROM THE COSTING, NOT DECIDED HERE. The loaded cost behind a
         determined answer is computed on the GBP 60,000 overhead placeholder
         unless a real figure was supplied, and on estimated rather than quoted
         surveyor costs. That does not make the answer unknown and the gate is
         not blocked on it — the placeholder is the published paper's own input
         and a gate that refused to run without a measured overhead could never
         run. But a decision taken on it is taken on an estimate and says so. */
      cost_basis_is_a_placeholder: cost ? !!cost.overhead_is_placeholder : null,

      /* What ON would do. Reported on every call, switch or no switch, so the
         moment the decision lands the answer is already there. */
      routes_to: (outcome === "FIRE") ? COME_BACK : null,
      enabled: !!CB_GATE_CONFIG.enabled,

      /* TRUE only when the switch is on AND the gate is determined AND it
         fires. This is the single boolean a renderer acts on; nothing should
         re-derive the conjunction for itself. */
      withholds_quote: !!CB_GATE_CONFIG.enabled && determined && outcome === "FIRE"
    };
  }

  return { assess: assess, COME_BACK: COME_BACK, OUTCOMES: OUTCOMES };
})();


/* ===========================================================================
   CB_BOOKING — the call-booking component.  PHASE 67.

   Absent from both journey documents. Specified as one component reachable from
   three points, and the third is the one everybody forgets.

   A GATED EXIT IS THE HIGHEST-VALUE PLACE TO OFFER A CALL. A client who has just
   been told they probably have no claim is the client most worth talking to:
   the gate may be wrong on their facts, and the reasoned-negative report is a
   product we already have. A funnel that offers a call only to people who are
   already succeeding is offering it to the people who need it least.
   =========================================================================== */
var CB_BOOKING = (function(){

  /* -------------------------------------------------------------------------
     REBUILT 3 SEPTEMBER 2026 (PHASES 69–71). THREE CHANNELS, AND VIDEO IS GONE.

     Video had been the default. It was also quietly carrying a second job — the
     surveyor pack asks whether a video walkthrough can replace a site visit, and
     this was where that was going to live. DROPPING VIDEO DOES NOT ANSWER THAT
     QUESTION, IT REMOVES THE PLACE THE ANSWER WAS GOING TO LIVE. If the surveyor
     says yes, video returns as a POST-ENGAGEMENT SURVEY STEP against the
     surveyor's diary — a different screen, a different calendar, a different
     owner. Do not quietly re-add it here.

     AND THIS IS NO LONGER AN OFFER ALONGSIDE THE FUNNEL. It is the CLOSE of it.
     The engagement letter moved to the back office on 3 September, so this
     screen — not the letter — is where a visitor becomes a lead, and it is
     where the assessment and the estimate are persisted. Account creation now
     follows it and is skippable, so nothing may wait for an account.
     ------------------------------------------------------------------------- */
  var CHANNELS = [
    { id:"phone", label:"Telephone", primary:true, booksASlot:true,
      capture:"phone",
      note:"the only channel that books a specific moment — it expands into a date and time picker" },
    { id:"sms_whatsapp", label:"Text message / WhatsApp", primary:false,
      capture:"phone",
      variants:["sms","whatsapp"],
      processor:true,
      note:"ONE choice to the client and TWO processors to us — the variant is recorded. WhatsApp is a third-party processor holding client contact data and must appear in the published privacy notice and on the processor list BEFORE the option renders" },
    { id:"email", label:"Email", primary:false,
      capture:"email",
      note:"captures and finishes. No picker — an email exchange does not need a slot, and offering one implies a promptness we may not keep" }
  ];

  /* Consent is captured PER CHANNEL, never once globally. The client picked a
     route; the consent is for that route. A single blanket "we may contact you"
     tick reused across three channels is the thing that turns a requested
     callback into a marketing complaint. Marketing is a separate, unticked box
     and is never a condition of submitting. */
  var CONSENTS = [
    { id:"contact_consent",  required:true,  preTicked:false, marketing:false,
      note:"per channel. Performing a service at their request, not consent to market" },
    { id:"marketing_optin",  required:false, preTicked:false, marketing:true,
      note:"PECR. Separate, unticked, worded as marketing, never bundled with the line above" }
  ];

  /* The person is captured HERE, not in the assessment and not at account
     creation — nothing personal is asked until the client has been given a
     figure. */
  var IDENTITY_FIELDS = ["full_name", "job_role", "job_role_other", "business_name"];

  var ENTRY_POINTS = ["funnel_close", "after_refined_range", "gated_exit"];

  function offerAt(point, ctx){
    ctx = ctx || {};
    if(ENTRY_POINTS.indexOf(point) === -1)
      return { offer:false, why:"not a booking entry point" };

    if(point === "gated_exit"){
      return { offer:true, prominence:"primary", skippable:false,
               heading:"Before you go — it is worth fifteen minutes.",
               body:"We have stopped the flow because of one answer. That answer may not be the whole picture, and where it is, there is usually still something to say about the spend that came after it.",
               channels:CHANNELS, consents:CONSENTS, identity:IDENTITY_FIELDS };
    }

    if(point === "funnel_close"){
      return { offer:true, prominence:"primary", skippable:false,
               heading:"To find out what you are entitled to",
               body:"The figure above is a ceiling built from a handful of answers. Turning it into a number you can rely on takes a conversation — leave us your details and pick how you would like us to reach you.",
               channels:CHANNELS, consents:CONSENTS, identity:IDENTITY_FIELDS,
               /* The lead is written HERE. Account creation is the next screen
                  and it is skippable, so a caller that defers persistence to it
                  loses the client entirely. */
               persistsLead:true, persistsAssessment:true, persistsEstimate:true };
    }

    return { offer:true, prominence:"primary", skippable:true,
             heading:"Talk it through with someone.",
             body:"A short call, and you will know whether this is worth taking further.",
             channels:CHANNELS, consents:CONSENTS, identity:IDENTITY_FIELDS };
  }

  /* Any channel flagged `processor` must be declared before it is switched on.
     Returning the list rather than a boolean so the caller has to look at it. */
  function processorChannels(){
    return CHANNELS.filter(function(c){ return c.processor; }).map(function(c){ return c.id; });
  }

  /* A channel whose processor is not yet declared MUST NOT RENDER. Building the
     option and documenting it afterwards is the wrong order, and it is the
     order everyone takes. */
  function renderableChannels(declaredProcessors){
    var declared = declaredProcessors || [];
    return CHANNELS.filter(function(c){
      return !c.processor || declared.indexOf(c.id) !== -1;
    });
  }

  /* Only the telephone books a moment. Everything else captures and finishes. */
  function booksASlot(channelId){
    var c = CHANNELS.filter(function(x){ return x.id === channelId; })[0];
    return !!(c && c.booksASlot);
  }

  return { CHANNELS:CHANNELS, CONSENTS:CONSENTS, IDENTITY_FIELDS:IDENTITY_FIELDS,
           ENTRY_POINTS:ENTRY_POINTS, offerAt:offerAt,
           processorChannels:processorChannels,
           renderableChannels:renderableChannels, booksASlot:booksASlot };
})();


/* ===========================================================================
   CB_BAND — the sector yield bands, in ONE place.  PHASE 72.

   Each of the five sector engines carries its own YIELD_BAND constant, and the
   condensed front door needs the same numbers to size its figure. Copying them
   into the funnel would create a second source of truth for the only number the
   client actually sees, and the two would drift — quietly, in the half of the
   system nobody re-reads.

   So the funnel reads THIS, and the harness asserts that every sector IIFE's own
   YIELD_BAND still matches it. The assertion is the point: it fails the day
   somebody tunes a band inside an engine and forgets the front door.

   These are ASSESSED bands — Caprebate's own reading of typical fixture density
   per sector — not independently calibrated. That qualifier travels with every
   figure they produce.
   =========================================================================== */
var CB_BAND = (function(){

  var BANDS = {
    care_homes:       { purchase:[0.20,0.40], new_build:[0.25,0.35], refurb_fitout:[0.60,0.90] },
    dental:           { purchase:[0.15,0.30], new_build:[0.30,0.40], refurb_fitout:[0.50,0.90] },
    supported_living: { purchase:[0.10,0.25], new_build:[0.10,0.25], refurb_fitout:[0.10,0.25] },
    gp:               { purchase:[0.15,0.30], new_build:[0.30,0.40], refurb_fitout:[0.40,0.70] },
    private_hospital: { purchase:[0.25,0.45], new_build:[0.35,0.45], refurb_fitout:[0.50,0.85] }
  };

  /* The front door's four triggers collapse onto the engines' three band keys.
     A refurbishment and a fit-out share a band; they do not share a method. */
  function bandKey(trigger){
    if(trigger === "purchase")  return "purchase";
    if(trigger === "new_build") return "new_build";
    if(trigger === "refurb" || trigger === "fit_out") return "refurb_fitout";
    return null;
  }

  function bandFor(sector, trigger){
    var k = bandKey(trigger);
    if(!k || !BANDS[sector]) return null;
    return BANDS[sector][k] || null;
  }

  /* Returns BOTH bounds. The screen displays the upper one as an "up to"
     ceiling; the stored run keeps the range, because a stored ceiling cannot be
     explained later or replayed after a CTA switch moves. */
  function rangeFor(sector, trigger, spend){
    var b = bandFor(sector, trigger);
    if(!b || typeof spend !== "number" || !(spend > 0)) return null;
    return { low: Math.round(spend * b[0]), high: Math.round(spend * b[1]), band:b };
  }

  /* PHASE 153e, 4 October 2026 (Word question 138, the surveyor's): supported living's range read for its own
     trigger, behind a switch that ships OFF. Today the calculation reads the refurbishment and fit-out band whatever
     the trigger; its three bands are identical (10% to 25%), so the switch changes no figure until the surveyor sets
     separate ranges from finished claims (the back end's src/web/sector-ranges.ts proposes them). A trigger list with
     more than one trigger takes the band with the LOWEST ceiling (never the one that relieves); no trigger: none. */
  var SWITCHES = { sl_band_by_trigger: false };
  function slBandKey(t){
    if(t === "purchase") return "purchase";
    if(t === "new_build") return "new_build";
    if(t === "conversion" || t === "fitout" || t === "fit_out" || t === "refurb") return "refurb_fitout";
    return null;
  }
  function slBand(triggers){
    var list = Array.isArray(triggers) ? triggers : (typeof triggers === "string" ? [triggers] : []);
    var best = null;
    for(var i = 0; i < list.length; i++){
      var k = slBandKey(list[i]);
      var b = k ? BANDS.supported_living[k] : null;
      if(b && (best === null || b[1] < best[1])) best = b;
    }
    return best;
  }

  return { BANDS:BANDS, bandKey:bandKey, bandFor:bandFor, rangeFor:rangeFor, SWITCHES:SWITCHES, slBandKey:slBandKey, slBand:slBand };
})();


/* ===========================================================================
   CB_FUNNEL — the condensed front door, WIRED IN.  PHASE 72.

   WHAT THIS REPLACES, AND WHY IT IS THE WHOLE POINT.

   Until now the assessment opened on a sector picker and then ran that sector's
   full engine at the client. A GP surgery met SEVENTEEN questions before seeing
   a number, out of fifty-two defined. That is a diligence questionnaire wearing
   a funnel's clothes, and the drop-off is in the middle of it.

   This module is the funnel: SIX SCREENS TO A FIGURE, for a client with one
   property. Everything the sector engines ask is still asked — LATER, of a
   client who has agreed to work with us, which is Stage 2. Nothing has been
   deleted; it has been MOVED to the side of the conversation where it belongs.

   THREE THINGS IT DELEGATES RATHER THAN REIMPLEMENTS, because a second
   implementation of any of them is how this corpus produces drift:
     · every gate and branch rule  -> CB_FRONTDOOR
     · the sector yield bands      -> CB_BAND
     · the contact channels and consents -> CB_BOOKING

   AND ONE THING IT DOES NOT DO. It fires no external call of any kind. The
   register derivation layer is switched off and stays off; every question it
   would have retired is still asked here.
   =========================================================================== */
var CB_FUNNEL = (function(){

  /* The six screens before the figure. This list IS the promise — if it grows,
     the condensation has been lost, and the harness asserts its length. */
  var SCREENS = ["Q1","Q1a","Q1b","Q1c","Q2","Q3"];

  var SECTOR_LABEL = {
    care_homes:"Care home", dental:"Dental practice",
    supported_living:"Supported living", gp:"GP / primary care",
    private_hospital:"Private hospital or clinic"
  };

  var TRIGGER_LABEL = {
    purchase:"I bought the property",
    new_build:"We built it — new build",
    refurb:"We refurbished or extended a property we already owned",
    fit_out:"We fitted out a property we lease"
  };

  var ENTITY_LABEL = {
    ltd:"Limited company", llp:"LLP", partnership:"Partnership",
    sole_trader:"Sole trader", unsure:"Not sure"
  };

  var ROLES = [
    ["owner_director","Owner / director"], ["partner_llp","Partner or LLP member"],
    ["sole_trader","Sole trader"], ["trustee","Trustee"],
    ["fd_cfo","Finance director / CFO"], ["controller","Financial controller or bookkeeper"],
    ["practice_manager","Practice manager"], ["registered_manager","Registered manager"],
    ["nominated_individual","Nominated individual"], ["ops_estates","Operations or estates manager"],
    ["company_secretary","Company secretary"], ["external_accountant","External accountant or adviser"],
    ["other","Something else"]
  ];

  function blankProperty(){
    return { address:null, sector:null, entity_type:null, trigger:null,
             spend:null, spend_unknown:false, date:null, date_unknown:false,
             lease_start_year:null,
             works:null, works_type:null, works_spend:null, works_spend_unknown:false,
             works_year:null, works_year_unknown:false };
  }

  function blankState(){
    return {
      own_prior_claim:null, previous_owner_claimed:null,
      is_uk_taxpayer:null, current_year_position:null,
      trigger_default:null,
      properties:[ blankProperty() ],
      contact:{ full_name:null, job_role:null, job_role_other:null,
                business_name:null, channel:null, sms_variant:null,
                contact_value:null, contact_consent:false, marketing_optin:false,
                slot_date:null, slot_time:null },
      account:{ created:false, skipped:false, email:null }
    };
  }

  /* ---------------------------------------------------------------------------
     THE FIGURE.

     Per property, then combined — and the breakdown is returned WITH the total
     rather than left for the caller to remember, because summing ceilings is
     the weakest number in this funnel and the breakdown is the only thing
     holding it honest.

     A property whose spend is unknown produces NO ceiling. It is not dropped
     silently and it is not given a default: it comes back marked, to be named
     on its own line. An unknown routes to capture, never to a guess.
     --------------------------------------------------------------------------- */
  function figure(state){
    var parts = (state.properties || []).map(function(p){
      if(p.spend_unknown || typeof p.spend !== "number" || !(p.spend > 0))
        return { address:p.address, sector:p.sector, ceiling:null,
                 incomplete:true, why:"we need a rough figure for this one" };

      var r = CB_BAND.rangeFor(p.sector, p.trigger, p.spend);
      if(!r) return { address:p.address, sector:p.sector, ceiling:null,
                      incomplete:true, why:"we could not size this one from what was given" };

      return { address:p.address, sector:p.sector,
               ceiling:r.high, low:r.low, high:r.high };
    });

    var c = CB_FRONTDOOR.combineCeilings(parts);
    c.incompleteProperties = parts.filter(function(p){ return p.incomplete; });
    c.condition = CB_FRONTDOOR.gateQ1b(state).condition || null;
    return c;
  }

  /* The assumptions list travels with the figure on every render. With the range
     collapsed to a single "up to" number this is the only guard left on it, so
     it is built here rather than assembled by whoever draws the screen. */
  function assumptions(state){
    var a = [
      "This is a ceiling, not a forecast — the top of a range, and researching the property moves it down, not up.",
      "It is sized by a sector yield band that is assessed, not independently calibrated.",
      "It is based only on what you have told us. No registers have been checked.",
      "Capital allowances are income or corporation tax relief — not capital gains tax."
    ];
    var cond = CB_FRONTDOOR.gateQ1b(state).condition;
    if(cond) a.unshift(cond);
    if(state.own_prior_claim === "yes" || state.own_prior_claim === "not sure")
      a.push("You have told us a claim may already have been made on these fixtures. That does not stop the assessment, but an adviser will go through it with you before any figure is relied on.");
    var f = figure(state);
    if(f.count > 1)
      a.push("Where more than one property is included, the headline adds the top of each property's range together. Each property is its own claim and each is assessed separately.");
    return a;
  }

  return { SCREENS:SCREENS, SECTOR_LABEL:SECTOR_LABEL, TRIGGER_LABEL:TRIGGER_LABEL,
           ENTITY_LABEL:ENTITY_LABEL, ROLES:ROLES,
           blankProperty:blankProperty, blankState:blankState,
           figure:figure, assumptions:assumptions };
})();



/* @@CAPREBATE-SLICE-CLOSE@@ */

module.exports = {
  CB_PLANT: CB_PLANT,
  CB_CTA: CB_CTA,
  CB_CTAQ: CB_CTAQ,
  CB_POOL: CB_POOL,
  CB_S25: CB_S25,
  CB_S33B: CB_S33B,
  CB_ELECTION: CB_ELECTION,
  CB_JURIS: CB_JURIS,
  CB_ACQ: CB_ACQ,
  CB_RATES: CB_RATES,
  CB_TAXPOS: CB_TAXPOS,
  CB_CASH: CB_CASH,
  CB_S187A: CB_S187A,
  CB_REGISTRY: CB_REGISTRY,
  CB_FRONTDOOR: CB_FRONTDOOR,
  CB_FEE: CB_FEE,
  CB_FEEGUARD: CB_FEEGUARD,
  CB_BENEFIT: CB_BENEFIT,
  CB_GATE_CONFIG: CB_GATE_CONFIG,
  CB_GATE: CB_GATE,
  CB_BOOKING: CB_BOOKING,
  CB_BAND: CB_BAND,
  CB_FUNNEL: CB_FUNNEL
};
